// The initials recorded against a part. The four technicians keep the codes
// already on every record they have ever made (WJ, XL, KM, R) - changing those
// would divorce new work from old. Anyone else gets the first letter of each
// part of their name, so Kee Seng is KS and John is J.
function initialsFor(user) {
  if (!user) return "";
  if (user.tech) return user.tech;
  return String(user.name || "")
    .split(/\s+/)
    .filter(Boolean)
    .map((w) => [...w][0])
    .join("")
    .toUpperCase()
    .slice(0, 4);
}

const GROUP_LABEL = {
  sales: "Sales",
  purchaser: "Purchaser",
  tech: "Technician 技术员",
  admin: "Admin",
};

const USER_KEY = "om_user";
// The group is still stored under the old key. Everything that already keyed
// off a role - the Chinese layer, the home buttons, the price permissions -
// keeps working, and a phone that had only a role set simply picks a name once.
const ROLE_KEY = "om_role";

function getUser() {
  try {
    const id = localStorage.getItem(USER_KEY) || "";
    return STAFF.find((u) => u.id === id) || null;
  } catch (_) { return null; }
}
function setUser(id) {
  const u = STAFF.find((s) => s.id === id) || null;
  try {
    if (u) { localStorage.setItem(USER_KEY, u.id); localStorage.setItem(ROLE_KEY, u.group); }
    else { localStorage.removeItem(USER_KEY); localStorage.removeItem(ROLE_KEY); }
  } catch (_) {}
}
// The person's name, for anything that records who did something.
function userName() {
  const u = getUser();
  return u ? u.name : "";
}
function getRole() {
  try { return localStorage.getItem(ROLE_KEY) || ""; } catch (_) { return ""; }
}
function setRole(role) {
  try {
    if (role) localStorage.setItem(ROLE_KEY, role);
    else localStorage.removeItem(ROLE_KEY);
  } catch (_) {}
}

// Draw the picker, grouped, so a long list stays scannable.
function renderStaffPicker() {
  const box = $("staff-list");
  if (!box) return;
  const order = ["sales", "purchaser", "tech", "admin"];
  box.innerHTML = order.map((g) => {
    const people = STAFF.filter((u) => u.group === g);
    if (!people.length) return "";
    return `
      <div class="staff-group">
        <p class="staff-group-title">${escapeHtml(GROUP_LABEL[g])}</p>
        <div class="staff-grid">
          ${people.map((u) => `
            <button type="button" class="staff-btn staff-${g}" data-user="${escapeAttr(u.id)}">
              <span class="staff-initial">${escapeHtml([...u.name][0] || "?")}</span>
              <span class="staff-name">${escapeHtml(u.name)}</span>
            </button>`).join("")}
        </div>
      </div>`;
  }).join("");
  box.querySelectorAll(".staff-btn").forEach((b) =>
    b.addEventListener("click", () => chooseUser(b.dataset.user))
  );
}

function chooseUser(id) {
  const next = STAFF.find((u) => u.id === id);
  if (!next) return;
  // The Chinese layer installs at page load, so moving into or out of the
  // technician group has to reload rather than re-translate a live page.
  const reload = (getRole() === "tech") !== (next.group === "tech");
  setUser(id);
  if (reload) { location.reload(); return; }
  applyRoleToHome();
  showScreen("home");
}
// Technician-only language toggle in the topbar. The preference lives in
// localStorage ("om_lang"); i18n.js reads it at page load, so flipping it
// reloads — the same pattern as switching roles. The label always shows the
// language you would switch TO, in that language.
function updateLangToggle() {
  const btn = $("lang-toggle");
  if (!btn) return;
  const isTech = getRole() === "tech";
  btn.style.display = isTech ? "inline-flex" : "none";
  if (!isTech) return;
  const inEnglish = localStorage.getItem("om_lang") === "en";
  btn.textContent = inEnglish ? "中文" : "English";
  // Both topbar pills carry margin-left:auto; with two visible, flexbox would
  // split them apart. The toggle takes the auto margin, Home sits beside it.
  $("home-link").style.marginLeft = "10px";
}
$("lang-toggle").addEventListener("click", () => {
  const inEnglish = localStorage.getItem("om_lang") === "en";
  localStorage.setItem("om_lang", inEnglish ? "zh" : "en");
  location.reload();
});

function applyRoleToHome() {
  const role = getRole();
  // Which home functions each account sees (per John's mapping, 28 Jul 2026):
  const ROLE_FUNCTIONS = {
    sales: ["new", "close", "view", "find", "ipl", "quote"],
    tech: ["open", "view", "find", "ipl"],
    // Purchaser is Sales plus requested parts, so it inherits the
    // IPLs too rather than being a separate shorter list.
    purchaser: ["new", "close", "view", "find", "ipl", "quote", "requests"],
    admin: ["new", "open", "close", "view", "find", "ipl", "quote", "requests"],
  };
  // An unknown group shows nothing rather than defaulting to Sales - silently
  // handing out someone else's functions is worse than an empty screen.
  const allowed = ROLE_FUNCTIONS[role] || [];
  document.querySelectorAll("#screen-home .home-btn").forEach((b) => {
    b.style.display = allowed.includes(b.dataset.go) ? "flex" : "none";
  });
  updateLangToggle();
  // Declared further down; guard so this is safe during startup.
  if (typeof refreshQuoteCount === "function") refreshQuoteCount();
  const badge = $("role-badge");
  if (badge) {
    // The name, not the group: on a personal phone "文建" answers "am I logged
    // in as me?" at a glance, which the group label never did.
    const u = getUser();
    const cls = role === "tech" ? "role-badge-tech"
      : role === "purchaser" ? "role-badge-purchase"
      : role === "admin" ? "role-badge-admin" : "role-badge-sales";
    badge.textContent = u ? u.name : (GROUP_LABEL[role] || "");
    badge.className = "role-badge " + cls;
  }
  updatePurchaserNotify(role);
}

// Purchaser-only: a banner at the top of home when parts are waiting to be
// ordered. Tapping it opens the Requested Parts list. Fails silently — a
// broken badge must never disturb the home screen.
async function updatePurchaserNotify(role) {
  const bar = $("pu-notify");
  if (!bar) return;
  if (role !== "purchaser") { bar.style.display = "none"; return; }
  try {
    const data = await api(`/api/part-requests/count`);
    const n = Number(data.count) || 0;
    if (n > 0) {
      bar.innerHTML = `🛒 <strong>${n} part${n === 1 ? "" : "s"}</strong> requested for ordering — tap to view`;
      bar.style.display = "block";
    } else {
      bar.style.display = "none";
    }
  } catch (_) {
    bar.style.display = "none";
  }
}
$("pu-notify").addEventListener("click", () => enterPurchaser());
function showScreen(name) {
  SCREENS.forEach((s) => $("screen-" + s).classList.toggle("active", s === name));
  // Home link visible everywhere except home/role
  $("home-link").style.display = (name === "home" || name === "role") ? "none" : "inline-flex";
  // The pad is sized when its popup opens, not here — it measures zero while
  // the popup is closed, whatever screen is showing.
  // Leaving the working context: hide the machine modal and stop any camera.
  if (name !== "slip") {
    const mm = $("machine-modal");
    if (mm) { mm.style.display = "none"; document.body.style.overflow = ""; }
    const om = $("order-modal");
    if (om) om.style.display = "none";
    try { stopQrScanner(); } catch (_) {}
  }
  window.scrollTo(0, 0);
}

async function goHome() {
  // Do not silently lose scanned-but-unsaved parts in the machine popup.
  if (session.pendingParts && session.pendingParts.length) {
    const ok = confirm(session.pendingParts.length + " scanned part(s) have not been saved. Discard them?");
    if (!ok) return;
    session.pendingParts = [];
  }
  // Save any in-progress repair comment before clearing the session.
  try { await saveCurrentComment(); } catch (_) {}
  try { stopQrScanner(); } catch (_) {}
  session.slipNumber = null; session.slip = null; session.machineId = null; session.technician = "";
  if (!getUser()) { renderStaffPicker(); showScreen("role"); return; }
  applyRoleToHome();
  showScreen("home");
}

// ---- API helpers -----------------------------------------------------------
async function api(path, opts) {
  const res = await fetch(`${API}${path}`, opts);
  let body = null;
  try { body = await res.json(); } catch (_) {}
  if (!res.ok) {
    const msg = (body && body.error) || `Request failed (${res.status})`;
    throw new Error(msg);
  }
  return body;
}

async function lookupItem(code) {
  return api(`/api/items/${encodeURIComponent(code)}`);
}

// ============================================================================
// REUSABLE SLIP SEARCH (used by Open, Close, View)
// Wires a text input + results container to the search endpoint, debounced.
// onPick(slipNumber) is called when the user taps a result.
// ============================================================================
function setupSlipSearch({ inputId, resultsId, scope, onPick }) {
  const input = $(inputId);
  const results = $(resultsId);
  let debounce = null;

  async function runSearch() {
    const q = input.value.trim();
    try {
      const data = await api(`/api/slips-search?q=${encodeURIComponent(q)}&scope=${scope}`);
      renderResults(data);
    } catch (e) {
      results.innerHTML = `<div class="slip-result-empty">Search failed</div>`;
    }
  }

  function renderResults(data) {
    const list = data.results || [];
    if (list.length === 0) {
      results.innerHTML = `<div class="slip-result-empty">${input.value.trim() ? "No matching slips" : "No slips yet"}</div>`;
      return;
    }
    results.innerHTML =
      list.map((s) =>
        `<button type="button" class="slip-result" data-slip="${escapeAttr(s.slip_number)}">
           <span class="sr-num">${escapeHtml(s.slip_number)}</span>
           <span class="sr-co">${escapeHtml(s.company)}</span>
           <span class="sr-status sr-${escapeAttr(s.status)}">${escapeHtml(STATUS_LABEL[s.status] || s.status)}</span>
         </button>`
      ).join("") +
      (data.hasMore ? `<div class="slip-result-more">Keep typing to narrow results…</div>` : "");

    results.querySelectorAll(".slip-result").forEach((btn) =>
      btn.addEventListener("click", () => {
        const num = btn.dataset.slip;
        // Mark selection visually
        results.querySelectorAll(".slip-result").forEach((b) => b.classList.remove("picked"));
        btn.classList.add("picked");
        onPick(num);
      })
    );
  }

  // Debounced typing
  input.addEventListener("input", () => {
    clearTimeout(debounce);
    debounce = setTimeout(runSearch, 250);
  });

  // Expose a reset that clears + shows recent slips
  return {
    reset() {
      input.value = "";
      results.innerHTML = `<div class="slip-result-empty">Loading…</div>`;
      runSearch();
    },
  };
}

