// ============================================================================
// NEW SERVICE
// ============================================================================
// ---- Machines on a new slip -------------------------------------------------
// Held here rather than read back off the form. Details are entered on a popup
// and only land in this list once "Add" is pressed, so a half-typed machine
// cannot be left sitting on the page and registered by accident.
let nsMachines = [];      // [{ model, qty, serial }]
let nsEditIndex = -1;     // -1 = adding, otherwise the entry being edited

function renderNsMachines() {
  const wrap = $("ns-machines");
  if (!nsMachines.length) {
    wrap.innerHTML = `<p class="ns-machines-empty">No machines added yet.</p>`;
    return;
  }
  wrap.innerHTML = nsMachines.map((m, i) => `
    <div class="ns-machine-card" data-i="${i}">
      <div class="ns-machine-main">
        <span class="ns-machine-model">${escapeHtml(m.model)}</span>
        ${m.qty > 1 ? `<span class="ns-machine-qty-tag">&times;${m.qty}</span>` : ""}
        ${m.serial ? `<span class="ns-machine-serial">S/N ${escapeHtml(m.serial)}</span>` : ""}
      </div>
      <div class="ns-machine-acts">
        <button type="button" class="ns-machine-edit" data-i="${i}" aria-label="Edit machine">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 17.5 17.5 3a2.1 2.1 0 0 1 3 3L6 20.5 2 21z"/></svg>
        </button>
        <button type="button" class="ns-machine-del" data-i="${i}" aria-label="Remove machine">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M18 6 6 18M6 6l12 12"/></svg>
        </button>
      </div>
    </div>`).join("");
  wrap.querySelectorAll(".ns-machine-edit").forEach((b) =>
    b.addEventListener("click", () => openMachineForm(Number(b.dataset.i))));
  wrap.querySelectorAll(".ns-machine-del").forEach((b) =>
    b.addEventListener("click", () => {
      nsMachines.splice(Number(b.dataset.i), 1);
      renderNsMachines();
    }));
}

function openMachineForm(index = -1) {
  nsEditIndex = index;
  const m = index >= 0 ? nsMachines[index] : { model: "", qty: 1, serial: "" };
  $("nsm-title").textContent = index >= 0 ? "Edit machine" : "Add machine";
  $("nsm-add").textContent = index >= 0 ? "Save" : "Add";
  $("nsm-model").value = m.model;
  $("nsm-qty").value = m.qty;
  $("nsm-serial").value = m.serial;
  $("nsm-status").innerHTML = "";
  nsmSerialHint();
  $("nsm-modal").style.display = "flex";
  document.body.style.overflow = "hidden";
  setTimeout(() => $("nsm-model").focus(), 50);
}

function closeMachineForm() {
  $("nsm-modal").style.display = "none";
  document.body.style.overflow = "";
  nsEditIndex = -1;
}

// Above one unit the serial box covers all of them, so say so rather than
// leaving someone to wonder which machine the number belongs to.
function nsmSerialHint() {
  const qty = Math.max(1, parseInt($("nsm-qty").value, 10) || 1);
  const hint = $("nsm-serial-hint");
  if (qty > 1) {
    hint.textContent = `This slip will list ${qty} separate machines. Anything typed here is recorded against all ${qty}.`;
    hint.style.display = "block";
  } else {
    hint.style.display = "none";
  }
}

function commitMachineForm() {
  const model = $("nsm-model").value.trim();
  if (!model) {
    $("nsm-status").innerHTML = statusErr("Model No. is required.");
    $("nsm-model").focus();
    return;
  }
  let qty = parseInt($("nsm-qty").value, 10);
  if (!Number.isFinite(qty) || qty < 1) qty = 1;
  const entry = { model, qty, serial: $("nsm-serial").value.trim() };
  if (nsEditIndex >= 0) nsMachines[nsEditIndex] = entry;
  else nsMachines.push(entry);
  closeMachineForm();
  renderNsMachines();
}

function resetNewServiceForm() {
  ["ns-company", "ns-contact-name", "ns-contact-number", "ns-whatsapp", "ns-notes"].forEach((id) => ($(id).value = ""));
  const same = $("ns-whatsapp-same"); if (same) same.checked = true;
  const wa = $("ns-whatsapp"); if (wa) wa.setAttribute("disabled", "true");
  const created = $("ns-created"); if (created) { created.style.display = "none"; created.innerHTML = ""; }
  const cs = $("ns-check-service"); if (cs) cs.checked = false;
  const qf = $("ns-quote-first"); if (qf) qf.checked = false;
  nsMachines = [];
  renderNsMachines();
  $("ns-status").innerHTML = "";
  const sug = $("ns-company-suggest"); if (sug) sug.innerHTML = "";
  nsDebtorCode = "";
  sigPadClear();
  renderSigPreview();
}

async function submitNewService() {
  const company = $("ns-company").value.trim();

  // Expand each machine row by its quantity. A row with qty >= 2 becomes
  // separate entries suffixed " - n/total" (e.g. "BK3410 - 1/2", "BK3410 - 2/2").
  // A row with qty 1 stays as-is ("BK3410"). Each entry becomes its own machine.
  // A quantity above one becomes that many separate machines on the slip, so
  // each can be repaired, commented on and priced independently. The serial
  // typed once is carried onto all of them - John's call: staff can list
  // several numbers in the one box when it matters.
  const machines = [];
  for (const m of nsMachines) {
    if (m.qty === 1) {
      machines.push({ desc: m.model, serial: m.serial });
    } else {
      for (let n = 1; n <= m.qty; n++) {
        machines.push({ desc: `${m.model} - ${n}/${m.qty}`, serial: m.serial });
      }
    }
  }

  if (!company) { $("ns-status").innerHTML = statusErr("Company is required."); return; }
  if (machines.length === 0) { $("ns-status").innerHTML = statusErr("Add at least one machine."); return; }

  // The signature is the customer accepting the printed terms, so a slip
  // cannot be registered without it. Scroll it into view rather than just
  // complaining — it sits below the fold on most phones.
  const signature = sigPadData();
  if (!signature) {
    $("ns-status").innerHTML = statusErr("Ask the customer to sign before registering.");
    openSigModal();
    return;
  }

  $("ns-submit").disabled = true;
  $("ns-status").innerHTML = statusInfo("Registering…");
  try {
    const slip = await api("/api/slips", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        company,
        // No debtor picked from AutoCount means a walk-in, which bills to
        // Cash Sales rather than being guessed at from the typed name.
        debtor_code: nsDebtorCode || CASH_SALES_DEBTOR,
        contact_name: $("ns-contact-name").value.trim(),
        contact_number: $("ns-contact-number").value.trim(),
        whatsapp_number: $("ns-whatsapp").value.trim(),
        check_service: $("ns-check-service").checked,
        quote_first: $("ns-quote-first").checked,
        notes: $("ns-notes").value.trim(),
        machines,
        signature,
      }),
    });
    toast(`Service slip ${slip.slip_number} created`, "ok");
    showSlipCreated(slip);
  } catch (e) {
    $("ns-status").innerHTML = statusErr(e.message);
  } finally {
    $("ns-submit").disabled = false;
  }
}

// After a slip is registered: show its number with Share (PDF) + Done actions.
function showSlipCreated(slip) {
  const panel = $("ns-created");
  if (!panel) { setTimeout(goHome, 1200); return; }
  panel.style.display = "block";
  panel.innerHTML = `
    <div class="created-card">
      <div class="created-check">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"><path d="M20 6 9 17l-5-5"/></svg>
      </div>
      <div class="created-title">Service slip ${escapeHtml(slip.slip_number)} created</div>
      <div class="created-sub">${escapeHtml(slip.company)} · ${slip.machines.length} machine(s)</div>
      <button class="btn-primary" id="ns-share" style="width:100%;margin-top:14px;">Share slip (PDF)</button>
      <button class="btn-secondary" id="ns-done" style="width:100%;margin-top:8px;">Done</button>
    </div>`;
  // Hide the form bits while the success card is up
  $("ns-status").innerHTML = "";
  $("ns-share").addEventListener("click", () => shareSlipPdf(slip));
  $("ns-done").addEventListener("click", goHome);
  window.scrollTo(0, 0);

  // Offered only when the server can actually send, so staff are never shown a
  // button that cannot work.
  whatsappStatus().then((wa) => {
    if (!wa.enabled || !wa.configured) return;
    const btn = document.createElement("button");
    btn.className = "btn-primary wa-send";
    btn.type = "button";
    btn.style.cssText = "width:100%;margin-top:8px;";
    btn.textContent = "Send to customer on WhatsApp";
    $("ns-share").insertAdjacentElement("beforebegin", btn);
    wireWhatsappButton(btn, slip, { auto: wa.auto_send });
  });
}

// ---- Service slip PDF ------------------------------------------------------
// The only part of OM Service a customer ever sees, so it is also where the
// terms live. Laid out at A4 in Helvetica (the only face jsPDF has built in).

// Terms & Conditions, as supplied by John (19 Aug 2026). Split into segments so
// the phrases he marked can be set bold mid-sentence. Wording is verbatim —
// do not reword these without asking; they are the terms customers sign against.
const SLIP_TERMS = [
  [
    { t: "Repaired equipment remaining unclaimed for a period exceeding " },
    { t: "Two Months (60 days)", b: true },
    { t: " may be disposed of at the sole discretion of Outboard & Marine Pte Ltd." },
  ],
  [
    { t: "Repair Assessment will be conducted free-of-charge. However, Outboard & Marine Pte Ltd will not be responsible for re-assembly of the assessed equipment should the client decide not to proceed with the repair. " },
    { t: "(Re-assembly surcharge of S$20.00 will be levied upon such request)", b: true },
  ],
  [
    { t: "Our standard Service & Repair package may include diagnosis & replacement of minor / peripheral components, etc. Repair duration would be less than 2 days." },
  ],
  [
    { t: "Our extended Services & Repair package may include cleaning, repair, and overhaul of key engine / product components and functional testing." },
  ],
  [
    { t: "Repair charges range from S$15.00 ~ S$80.00 (EXCLUDING Cost of spare parts & prevailing GST) " },
    { t: "NOT APPLICABLE", b: true },
    { t: " for Chipper Shredders. Vehicle mounted application equipment are subject to individualised quotation." },
  ],
  [
    { t: "The client agrees to proceed for repair without quotation if price does not exceed S$120.00 for all other equipment brands." },
  ],
];

// Lay out mixed normal/bold runs with word wrapping. jsPDF has no rich text, so
// each word is measured and placed individually. Pass draw=false to measure a
// block without rendering it — used to balance the two-column terms.
// Returns the final baseline y.
function pdfFlowRich(doc, segments, x, y, maxW, size, leading, draw = true) {
  doc.setFontSize(size);
  let cx = x;
  let cy = y;
  for (const seg of segments) {
    doc.setFont("helvetica", seg.b ? "bold" : "normal");
    for (const word of seg.t.split(/(\s+)/)) {
      if (!word) continue;
      const isSpace = !/\S/.test(word);
      const w = doc.getTextWidth(word);
      if (!isSpace && cx + w > x + maxW) {
        cy += leading;
        cx = x;
      }
      if (isSpace && cx === x) continue;   // never start a line with a space
      if (draw) doc.text(word, cx, cy);
      cx += w;
    }
  }
  return cy;
}

// Width a letterspaced string will actually occupy. jsPDF measures text with
// char spacing ignored, so anything that positions against a label's width has
// to add it back by hand.
function pdfSpacedWidth(doc, text, space) {
  return doc.getTextWidth(text) + space * Math.max(0, text.length - 1);
}

// Small letterspaced label, the workhorse of this layout. jsPDF's char spacing
// is global state, so it is always reset before returning.
//
// Right alignment is corrected manually for the same reason: jsPDF anchors on
// the unspaced width, so a right-aligned label overruns its anchor by the
// spacing and collides with whatever sits beside it.
function pdfLabel(doc, text, x, y, { size = 6.6, space = 1.6, grey = 150, bold = true, align } = {}) {
  doc.setFontSize(size);
  doc.setFont("helvetica", bold ? "bold" : "normal");
  doc.setTextColor(grey);
  if (align === "right") {
    doc.setCharSpace(space);
    doc.text(text, x - pdfSpacedWidth(doc, text, space), y);
    doc.setCharSpace(0);
    return;
  }
  doc.setCharSpace(space);
  doc.text(text, x, y, align ? { align } : undefined);
  doc.setCharSpace(0);
}

// Build the service-slip PDF (jsPDF) and return a Blob.
//
// Layout: hierarchy carried by type size, weight and letterspacing rather than
// boxes, with a single teal rule under the header as the only colour. The
// header is the leaf mark plus the company wordmark, with the address set as
// live text — which is also why the website line is correct here even though
// the old letterhead image had it wrong.
function buildSlipPdf(slip) {
  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({ unit: "pt", format: "a4" });

  const LEFT = 48;
  const RIGHT = 547;
  const W = RIGHT - LEFT;
  const BOTTOM = 772;
  const TEAL = [13, 116, 122];
  const TEAL_TINT = [237, 246, 246];
  const BORDER = [219, 225, 227];
  const INK = 26;
  let y = 46;

  const setDraw = (c) => Array.isArray(c) ? doc.setDrawColor(c[0], c[1], c[2]) : doc.setDrawColor(c);
  const setFill = (c) => Array.isArray(c) ? doc.setFillColor(c[0], c[1], c[2]) : doc.setFillColor(c);
  const setText = (c) => Array.isArray(c) ? doc.setTextColor(c[0], c[1], c[2]) : doc.setTextColor(c);

  const need = (h) => {
    if (y + h <= BOTTOM) return false;
    doc.addPage();
    y = 54;
    return true;
  };

  // ---- Small outline icons -------------------------------------------------
  // jsPDF has no icon font, so these are drawn from primitives. Deliberately
  // simple: at 11pt anything more detailed turns to mush on a printed slip.
  function icon(name, ix, iy, s) {
    setDraw(TEAL); doc.setLineWidth(0.9);
    const m = s / 12;
    if (name === "calendar") {
      doc.roundedRect(ix, iy + 1.5 * m, 12 * m, 10 * m, 1.2 * m, 1.2 * m);
      doc.line(ix, iy + 4.5 * m, ix + 12 * m, iy + 4.5 * m);
      doc.line(ix + 3.5 * m, iy, ix + 3.5 * m, iy + 3 * m);
      doc.line(ix + 8.5 * m, iy, ix + 8.5 * m, iy + 3 * m);
    } else if (name === "building") {
      doc.rect(ix + 1 * m, iy, 10 * m, 11.5 * m);
      doc.line(ix + 3.6 * m, iy + 3 * m, ix + 5 * m, iy + 3 * m);
      doc.line(ix + 7 * m, iy + 3 * m, ix + 8.4 * m, iy + 3 * m);
      doc.line(ix + 3.6 * m, iy + 6 * m, ix + 5 * m, iy + 6 * m);
      doc.line(ix + 7 * m, iy + 6 * m, ix + 8.4 * m, iy + 6 * m);
      doc.line(ix + 5.2 * m, iy + 11.5 * m, ix + 5.2 * m, iy + 8.8 * m);
      doc.line(ix + 6.8 * m, iy + 11.5 * m, ix + 6.8 * m, iy + 8.8 * m);
      doc.line(ix + 5.2 * m, iy + 8.8 * m, ix + 6.8 * m, iy + 8.8 * m);
    } else if (name === "person") {
      doc.circle(ix + 6 * m, iy + 3.6 * m, 2.7 * m);
      doc.lines([[0, -3.2 * m], [1.7 * m, -1.9 * m], [4.6 * m, 0], [1.7 * m, 1.9 * m], [0, 3.2 * m]],
        ix + 1 * m, iy + 11.6 * m);
    } else if (name === "phone") {
      doc.roundedRect(ix + 2.6 * m, iy, 6.8 * m, 12 * m, 1.4 * m, 1.4 * m);
      doc.line(ix + 4.8 * m, iy + 1.8 * m, ix + 7.2 * m, iy + 1.8 * m);
      setFill(TEAL);
      doc.circle(ix + 6 * m, iy + 9.9 * m, 0.7 * m, "F");
    } else if (name === "gear") {
      // Six short, stubby teeth. Four long ones read as a snowflake.
      doc.circle(ix + 6 * m, iy + 6 * m, 3.6 * m);
      doc.circle(ix + 6 * m, iy + 6 * m, 1.5 * m);
      doc.setLineWidth(1.5);
      for (let i = 0; i < 6; i++) {
        const a = (Math.PI / 3) * i;
        doc.line(ix + 6 * m + Math.cos(a) * 3.6 * m, iy + 6 * m + Math.sin(a) * 3.6 * m,
                 ix + 6 * m + Math.cos(a) * 5.5 * m, iy + 6 * m + Math.sin(a) * 5.5 * m);
      }
      doc.setLineWidth(0.9);
    } else if (name === "clipboard") {
      doc.roundedRect(ix + 1 * m, iy + 1.6 * m, 10 * m, 10.4 * m, 1.2 * m, 1.2 * m);
      doc.roundedRect(ix + 4 * m, iy, 4 * m, 3 * m, 0.8 * m, 0.8 * m);
      doc.line(ix + 3.4 * m, iy + 6 * m, ix + 8.6 * m, iy + 6 * m);
      doc.line(ix + 3.4 * m, iy + 8.6 * m, ix + 7 * m, iy + 8.6 * m);
    } else if (name === "shield") {
      // The last segment closes the path back up the left edge. Without it the
      // shield ends at the bottom-left corner and its left side is simply
      // missing, which reads as the icon being clipped.
      doc.lines([[5 * m, -1.9 * m], [5 * m, 1.9 * m], [0, 4.8 * m], [-5 * m, 4.9 * m],
                 [-5 * m, -4.9 * m], [0, -4.8 * m]],
        ix + 1 * m, iy + 2.3 * m);
      doc.line(ix + 3.7 * m, iy + 6 * m, ix + 5.3 * m, iy + 7.7 * m);
      doc.line(ix + 5.3 * m, iy + 7.7 * m, ix + 8.5 * m, iy + 4.4 * m);
    } else if (name === "info") {
      doc.circle(ix + 6 * m, iy + 6 * m, 5.2 * m);
      setFill(TEAL);
      doc.circle(ix + 6 * m, iy + 3.5 * m, 0.75 * m, "F");
      doc.setLineWidth(1.1);
      doc.line(ix + 6 * m, iy + 5.5 * m, ix + 6 * m, iy + 8.8 * m);
    }
  }

  // A teal section heading with its icon, as on the printed copy.
  function sectionHead(label, ic) {
    icon(ic, LEFT, y - 8.5, 11);
    doc.setFontSize(9); doc.setFont("helvetica", "bold");
    setText(TEAL); doc.setCharSpace(0.9);
    doc.text(label, LEFT + 17, y);
    doc.setCharSpace(0);
    y += 12;
  }

  // ---- Header: mark + wordmark, address set as text ----
  const MARK = 46;
  let headBottom = y + MARK;
  try {
    doc.addImage(OM_MARK, "PNG", LEFT, y, MARK, MARK);
  } catch (_) { /* fall through to text below */ }
  try {
    const nameW = 208;
    const nameH = nameW / OM_NAMEBLOCK_RATIO;
    doc.addImage(OM_NAMEBLOCK, "PNG", LEFT + MARK + 13, y + (MARK - nameH) / 2, nameW, nameH);
  } catch (_) {
    doc.setFontSize(15); doc.setFont("helvetica", "bold"); setText(INK);
    doc.text("Outboard & Marine Pte Ltd", LEFT + MARK + 13, y + 28);
  }

  doc.setFontSize(6.9); doc.setFont("helvetica", "normal"); setText(105);
  const addr = [
    "9 Kaki Bukit Rd 1, #01-03, Eunos Technolink, Singapore 415938",
    "Tel (65) 6743 4039   ·   Fax (65) 6748 2031",
    "sales@omprotools.com.sg   ·   www.gardenequipment.com.sg",
    "GST M2-0009392-5   ·   Co. Reg. 196800629G",
  ];
  let ay = y + 11;
  addr.forEach((line) => { doc.text(line, RIGHT, ay, { align: "right" }); ay += 9.2; });
  headBottom = Math.max(headBottom, ay - 5);

  y = headBottom + 10;
  setDraw(TEAL); doc.setLineWidth(1.8);
  doc.line(LEFT, y, RIGHT, y);
  y += 30;

  // ---- Title + slip number panel ----
  const BOX_W = 158, BOX_H = 58, BAND_H = 19;
  doc.setFontSize(25); doc.setFont("helvetica", "bold"); setText(TEAL);
  doc.text("Service Slip", LEFT, y + 6);
  doc.setFontSize(9.2); doc.setFont("helvetica", "normal"); setText(120);
  doc.text("Customer Acknowledgement Copy", LEFT, y + 21);

  const boxX = RIGHT - BOX_W, boxY = y - 15;
  setFill(TEAL);
  doc.roundedRect(boxX, boxY, BOX_W, BAND_H + 6, 4, 4, "F");
  setFill(255); setDraw(TEAL); doc.setLineWidth(1.1);
  doc.rect(boxX, boxY + BAND_H, BOX_W, BOX_H - BAND_H, "FD");
  doc.setFontSize(7.4); doc.setFont("helvetica", "bold"); setText(255);
  doc.setCharSpace(1.6);
  doc.text("SLIP NO.", boxX + BOX_W / 2, boxY + 13.5, { align: "center" });
  doc.setCharSpace(0);
  doc.setFontSize(23); setText(INK);
  doc.text(String(slip.slip_number || ""), boxX + BOX_W / 2, boxY + BOX_H - 11, { align: "center" });

  y = boxY + BOX_H + 24;

  // ---- Meta card: four fields, each with an icon ----
  const META_H = 56;
  setDraw(BORDER); setFill(252); doc.setLineWidth(0.8);
  doc.roundedRect(LEFT, y, W, META_H, 5, 5, "FD");
  const meta = [
    ["calendar", "DATE RECEIVED", formatDate(slip.created_at) || "—"],
    ["building", "COMPANY", slip.company || "—"],
    ["person", "CONTACT", slip.contact_name || "—"],
    ["phone", "CONTACT NO.", slip.contact_number || "—"],
  ];
  const cellW = W / 4;
  meta.forEach(([ic, label, value], i) => {
    const cx = LEFT + i * cellW;
    if (i) {
      setDraw(BORDER); doc.setLineWidth(0.7);
      doc.line(cx, y + 10, cx, y + META_H - 10);
    }
    icon(ic, cx + 14, y + 14, 11);
    doc.setFontSize(6.6); doc.setFont("helvetica", "bold"); setText(140);
    doc.setCharSpace(1.1);
    doc.text(label, cx + 31, y + 22);
    doc.setCharSpace(0);
    doc.setFontSize(11); doc.setFont("helvetica", "bold"); setText(INK);
    doc.text(doc.splitTextToSize(String(value), cellW - 28)[0] || "", cx + 14, y + 43);
  });
  y += META_H + 26;

  // ---- Equipment table ----
  sectionHead("EQUIPMENT RECEIVED", "gear");
  y += 4;

  const NO_W = 46, RET_W = 96, DESC_W = W - NO_W - RET_W;
  const drawTableHead = () => {
    setFill(TEAL);
    doc.rect(LEFT, y, W, 21, "F");
    doc.setFontSize(7); doc.setFont("helvetica", "bold"); setText(255);
    doc.setCharSpace(1.2);
    doc.text("NO.", LEFT + NO_W / 2, y + 13.5, { align: "center" });
    doc.text("EQUIPMENT DESCRIPTION", LEFT + NO_W + 14, y + 13.5);
    doc.text("RETURNED", LEFT + NO_W + DESC_W + RET_W / 2, y + 13.5, { align: "center" });
    doc.setCharSpace(0);
    y += 21;
  };
  drawTableHead();

  (slip.machines || []).forEach((m, i) => {
    // Set the font BEFORE measuring. splitTextToSize measures at whatever size
    // was last set, so leaving the serial's 8pt in place made the next row
    // measure narrow, skip its wrap, and then print at 9.6pt straight through
    // the RETURNED column.
    doc.setFontSize(9.6); doc.setFont("helvetica", "normal");
    const lines = doc.splitTextToSize(String(m.machine_desc || ""), DESC_W - 26);
    const serial = String(m.serial_no || "").trim();
    doc.setFontSize(8);
    const serialLines = serial ? doc.splitTextToSize("S/N " + serial, DESC_W - 26) : [];
    const rowH = Math.max(30, 16 + lines.length * 12 + serialLines.length * 10);
    if (need(rowH + 30)) drawTableHead();

    setDraw(BORDER); setFill(255); doc.setLineWidth(0.7);
    doc.rect(LEFT, y, W, rowH, "FD");
    doc.line(LEFT + NO_W, y, LEFT + NO_W, y + rowH);
    doc.line(LEFT + NO_W + DESC_W, y, LEFT + NO_W + DESC_W, y + rowH);

    doc.setFontSize(9.6); doc.setFont("helvetica", "normal"); setText(120);
    doc.text(String(i + 1), LEFT + NO_W / 2, y + 19, { align: "center" });
    setText(INK);
    doc.text(lines, LEFT + NO_W + 14, y + 19);
    if (serialLines.length) {
      doc.setFontSize(8); setText(125);
      doc.text(serialLines, LEFT + NO_W + 14, y + 19 + lines.length * 12);
    }
    // Ticked by hand when the equipment goes back to the customer.
    setDraw(150); doc.setLineWidth(0.8); setFill(255);
    doc.rect(LEFT + NO_W + DESC_W + RET_W / 2 - 6, y + rowH / 2 - 6, 12, 12, "FD");
    y += rowH;
  });
  y += 26;

  // ---- Requested ----
  const requests = [];
  if (slip.check_service) requests.push("CHECK & SERVICE FOR ALL");
  if (slip.quote_first) requests.push("QUOTE FIRST");
  if (requests.length) {
    need(58);
    sectionHead("REQUESTED", "clipboard");
    y += 4;
    const boxH = 16 + requests.length * 15;
    setDraw(BORDER); setFill(TEAL_TINT); doc.setLineWidth(0.8);
    doc.roundedRect(LEFT, y, W, boxH, 5, 5, "FD");
    doc.setFontSize(10); doc.setFont("helvetica", "bold"); setText(INK);
    requests.forEach((r, i) => doc.text(r, LEFT + 16, y + 20 + i * 15));
    y += boxH + 24;
  }

  // ---- Notes ----
  if (slip.notes) {
    const lines = doc.splitTextToSize(String(slip.notes), W - 32);
    need(lines.length * 12 + 46);
    sectionHead("NOTES", "clipboard");
    y += 4;
    const boxH = 16 + lines.length * 12;
    setDraw(BORDER); setFill(252); doc.setLineWidth(0.8);
    doc.roundedRect(LEFT, y, W, boxH, 5, 5, "FD");
    doc.setFontSize(9.4); doc.setFont("helvetica", "normal"); setText(60);
    doc.text(lines, LEFT + 16, y + 18);
    y += boxH + 24;
  }

  // ---- Terms, balanced across two columns ----
  const T_SIZE = 7.2, T_LEAD = 9.6, T_GAP = 34;
  const tColW = (W - T_GAP) / 2 - 22;
  // Measure exactly what drawColumn advances, or the estimate drifts. It used
  // to add a separator for every item including the last, overshooting by 9pt
  // per column - enough to push the signature onto a page of its own.
  const SEP_H = 9;
  const heights = SLIP_TERMS.map((segs) => {
    const end = pdfFlowRich(doc, segs, 0, 0, tColW, T_SIZE, T_LEAD, false);
    return end + T_LEAD + 4;
  });
  const colHeightOf = (items) =>
    items.reduce((a, b) => a + b, 0) + Math.max(0, items.length - 1) * SEP_H;
  const totalH = colHeightOf(heights);
  let split = SLIP_TERMS.length, run = 0;
  for (let i = 0; i < heights.length; i++) {
    run += heights[i] + SEP_H;
    if (run >= totalH / 2) { split = i + 1; break; }
  }
  const colHeight = Math.max(
    colHeightOf(heights.slice(0, split)),
    colHeightOf(heights.slice(split))
  );

  need(colHeight + 46);
  sectionHead("TERMS & CONDITIONS", "shield");
  y += 8;

  const drawColumn = (items, startIndex, x, startY) => {
    let cy = startY;
    items.forEach((segs, n) => {
      // Numbered in a teal ring, the way the printed copy reads.
      setDraw(TEAL); setFill(255); doc.setLineWidth(0.8);
      doc.circle(x + 7, cy - 2.6, 7, "FD");
      doc.setFontSize(6.8); doc.setFont("helvetica", "bold"); setText(TEAL);
      doc.text(String(startIndex + n + 1), x + 7, cy - 0.4, { align: "center" });
      setText(62);
      const end = pdfFlowRich(doc, segs, x + 20, cy, tColW, T_SIZE, T_LEAD);
      cy = end + T_LEAD + 4;
      if (n < items.length - 1) {
        setDraw(232); doc.setLineWidth(0.6);
        doc.setLineDashPattern([1.4, 1.8], 0);
        doc.line(x, cy, x + tColW + 20, cy);
        doc.setLineDashPattern([], 0);
        cy += 9;
      }
    });
    return cy;
  };
  drawColumn(SLIP_TERMS.slice(0, split), 0, LEFT, y);
  drawColumn(SLIP_TERMS.slice(split), split, LEFT + W / 2 + T_GAP / 2, y);
  y += colHeight + 22;

  // ---- Signature ----
  // Customer only: the counter staff are already identified by the letterhead.
  // Pinned to the foot of the last page rather than left to flow. A slip with
  // enough machines to need a second page used to strand the signature half
  // way down it, which reads as though the document carries on.
  const SIG_H = 66;
  const SIG_BOTTOM = 786;          // just clear of the footer rule at 800
  const sigY = SIG_BOTTOM - SIG_H;
  if (y > sigY) { doc.addPage(); }
  y = sigY;
  setDraw(BORDER); setFill(255); doc.setLineWidth(0.8);
  doc.roundedRect(LEFT, y, W, SIG_H, 5, 5, "FD");
  const sigLineY = y + SIG_H - 22;
  const sigW = 250;
  if (slip.signature) {
    try {
      const props = doc.getImageProperties(slip.signature);
      const maxH = 32, maxW = sigW - 24;
      const scale = Math.min(maxW / props.width, maxH / props.height);
      doc.addImage(slip.signature, "PNG", LEFT + 22,
        sigLineY - props.height * scale - 3, props.width * scale, props.height * scale);
    } catch (_) { /* a bad image must never stop the slip printing */ }
  }
  setDraw(90); doc.setLineWidth(0.8);
  doc.line(LEFT + 18, sigLineY, LEFT + 18 + sigW, sigLineY);
  doc.setFontSize(6.8); doc.setFont("helvetica", "bold"); setText(TEAL);
  doc.setCharSpace(1.1);
  doc.text("CUSTOMER SIGNATURE   ·   I ACCEPT THE TERMS ABOVE", LEFT + 18, sigLineY + 14);
  doc.setCharSpace(0);

  // ---- Page footers ----
  const pages = doc.getNumberOfPages();
  for (let p = 1; p <= pages; p++) {
    doc.setPage(p);
    setDraw(228); doc.setLineWidth(0.7);
    doc.line(LEFT, 800, RIGHT, 800);
    icon("info", LEFT, 807, 10);
    doc.setFontSize(7.4); doc.setFont("helvetica", "normal"); setText(120);
    doc.text(
      "Please quote Slip No. " + String(slip.slip_number || "") + " when enquiring about your equipment.",
      LEFT + 16, 816
    );
    doc.text("Page " + p + " of " + pages, RIGHT, 816, { align: "right" });
  }

  return doc.output("blob");
}
// ---- Sending the slip to the customer on WhatsApp --------------------------
// Asked once and remembered: whether the server is set up to send at all, and
// whether it should send without being asked. Both live on the server so
// switching to automatic is a setting there, not an app deploy.
let waStatusPromise = null;
function whatsappStatus() {
  if (!waStatusPromise) {
    waStatusPromise = api("/api/whatsapp/status")
      .catch(() => ({ enabled: false, configured: false, auto_send: false }));
  }
  return waStatusPromise;
}

// The PDF is built here, in the browser, by the same code that produces the
// copy staff look at - then posted up as raw bytes. Sending the finished file
// rather than asking the server to rebuild it means the customer cannot
// receive a subtly different document from the one that was signed.
async function sendSlipWhatsApp(slip, { auto = false } = {}) {
  let blob;
  try {
    blob = buildSlipPdf(slip);
  } catch (e) {
    return { ok: false, error: "Couldn't build the PDF: " + e.message };
  }
  const params = new URLSearchParams();
  const me = userName();
  if (me) params.set("who", me);
  params.set("role", getRole());
  if (auto) params.set("auto", "1");

  try {
    const r = await api(
      `/api/slips/${encodeURIComponent(slip.slip_number)}/whatsapp?${params.toString()}`,
      { method: "POST", headers: { "Content-Type": "application/pdf" }, body: blob }
    );
    return { ok: true, to: r.to };
  } catch (e) {
    return { ok: false, error: e.message || "Could not send on WhatsApp." };
  }
}

// One button, used on the success card and again in View Slips - the second
// one matters, because a send that fails needs somewhere to be retried from.
function wireWhatsappButton(btn, slip, { auto = false } = {}) {
  const idle = btn.textContent;
  const run = async (isAuto) => {
    btn.disabled = true;
    btn.textContent = isAuto ? "Sending to customerâ€¦" : "Sendingâ€¦";
    const r = await sendSlipWhatsApp(slip, { auto: isAuto });
    if (r.ok) {
      btn.textContent = "Sent to " + r.to;
      btn.classList.add("wa-sent");
      toast("Slip sent on WhatsApp", "ok");
    } else {
      btn.disabled = false;
      btn.textContent = idle;
      // Left on screen rather than a toast that vanishes: a failed send is
      // something someone has to act on.
      toast(r.error, "err");
    }
  };
  btn.addEventListener("click", () => run(false));
  if (auto) run(true);
}

// Share the PDF via the device's native share sheet (WhatsApp/email/AirDrop),
// falling back to a plain download where sharing files isn't supported.
async function shareSlipPdf(slip) {
  let blob;
  try {
    blob = buildSlipPdf(slip);
  } catch (e) {
    toast("Couldn't build PDF: " + e.message, "err");
    return;
  }
  const filename = `ServiceSlip_${slip.slip_number}.pdf`;
  const file = new File([blob], filename, { type: "application/pdf" });

  // Native file share (mobile): includes WhatsApp, Mail, AirDrop, etc.
  if (navigator.canShare && navigator.canShare({ files: [file] })) {
    try {
      await navigator.share({ files: [file], title: `Service Slip ${slip.slip_number}` });
      return;
    } catch (_) { /* user cancelled or share failed — fall through to download */ }
  }

  // Fallback: trigger a download (desktop, or browsers without file share).
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url; a.download = filename;
  document.body.appendChild(a); a.click(); a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 4000);
}

function statusErr(m) { return `<span class="led" style="background:var(--amber);box-shadow:0 0 0 3px var(--amber-tint)"></span> ${escapeHtml(m)}`; }
function statusInfo(m) { return `<span class="led"></span> ${escapeHtml(m)}`; }
function statusOk(m) { return `<span class="led" style="background:#38A32A;box-shadow:0 0 0 3px rgba(56,163,42,.18)"></span> ${escapeHtml(m)}`; }

// ============================================================================
// OPEN SERVICE
// ============================================================================
// ---- Open Service: slip list -> slip detail -> machine modal ---------------
async function enterOpenService() {
  showScreen("open");
  session.slipNumber = null; session.slip = null; session.machineId = null;
  session.technician = ""; session.pendingParts = [];
  $("os-slip-list").innerHTML = `<div class="fp-loading">Loading slips…</div>`;
  try {
    session.allSlips = await api(`/api/slips?status=working`);
    renderSlipList();
  } catch (e) {
    $("os-slip-list").innerHTML = "";
    toast(e.message, "err");
  }
}

// Render the active-slip list, filtered by the search box (number or company).
function renderSlipList() {
  const q = ($("os-search").value || "").trim().toLowerCase();
  const list = (session.allSlips || []).filter((s) =>
    !q || s.slip_number.includes(q) || (s.company || "").toLowerCase().includes(q)
  );
  const wrap = $("os-slip-list");
  if (!list.length) {
    wrap.innerHTML = `<div class="fp-empty">${q ? "No slips match" : "No open slips"}</div>`;
    return;
  }
  // Newest first
  const sorted = [...list].sort((a, b) => b.slip_number.localeCompare(a.slip_number));
  wrap.innerHTML = sorted.map((s) => `
    <button type="button" class="slip-card" data-slip="${escapeAttr(s.slip_number)}">
      <div class="slip-card-top">
        <strong>${escapeHtml(s.slip_number)}</strong>
        <span class="vs-status vs-${escapeAttr(s.status)}">${escapeHtml(STATUS_LABEL[s.status] || s.status)}</span>
      </div>
      <div class="slip-card-co">${escapeHtml(s.company)}</div>
      <div class="slip-card-sub">${(s.machines || []).length} machine${(s.machines || []).length === 1 ? "" : "s"}${s.created_at ? " · " + escapeHtml(formatDate(s.created_at)) : ""}</div>
    </button>`).join("");
  wrap.querySelectorAll(".slip-card").forEach((btn) =>
    btn.addEventListener("click", () => onSlipChosen(btn.dataset.slip))
  );
}
$("os-search").addEventListener("input", renderSlipList);
$("sd-back").addEventListener("click", enterOpenService);

async function onSlipChosen(slipNumber) {
  if (!slipNumber) return;
  try {
    session.slip = await api(`/api/slips/${encodeURIComponent(slipNumber)}`);
    session.slipNumber = slipNumber;
    session.machineId = null;
    showScreen("slip");
    renderSlipScreen();
  } catch (e) {
    toast(e.message, "err");
  }
}

// The slip-detail screen: header card, machines as buttons, status actions.
function renderSlipScreen() {
  const slip = session.slip;
  if (!slip) return;

  const meta = [];
  if (slip.contact_name) meta.push(`Contact: ${escapeHtml(slip.contact_name)}`);
  if (slip.contact_number) meta.push(escapeHtml(slip.contact_number));
  const created = formatDate(slip.created_at);

  $("sd-head").innerHTML = `
    <div class="vs-card">
      <div class="vs-head">
        <div>
          <div class="vs-company">${escapeHtml(slip.company)}</div>
          <div class="vs-sub">Slip ${escapeHtml(slip.slip_number)}${created ? " · Created " + escapeHtml(created) : ""}</div>
        </div>
        <span class="vs-status vs-${escapeAttr(slip.status)}" id="os-status-badge">${escapeHtml(STATUS_LABEL[slip.status] || slip.status)}</span>
      </div>
      ${meta.length ? `<div class="vs-sub">${meta.join(" · ")}</div>` : ""}
      ${slip.notes ? `<div class="vs-notes">${escapeHtml(slip.notes)}</div>` : ""}
    </div>
    ${(slip.check_service || slip.quote_first) ? `
    <div class="sd-requests">
      ${slip.check_service ? `<div class="sd-req sd-req-service">✓ Check &amp; Service for all</div>` : ""}
      ${slip.quote_first ? `<div class="sd-req sd-req-quote">💬 Quote first</div>` : ""}
    </div>` : ""}`;

  // Machines as tappable buttons with per-machine progress.
  $("sd-machines").innerHTML = slip.machines.map((m) => {
    const parts = m.parts || [];
    const labour = Number(m.labour_charge) || 0;
    let total = labour; for (const p of parts) total += p.unit_price * p.quantity;
    const hasComment = !!String(m.repair_comment || "").trim();
    const worked = parts.length > 0 || hasComment || labour > 0;
    // Quoting is per machine, so the state has to be visible per machine -
    // otherwise the only way to find out which one is waiting is to open each.
    const q = m.quote_status || "";
    const qTag = q === "NEED_QUOTE" ? `<span class="machine-quote mq-need">Waiting to quote</span>`
               : q === "QUOTED"     ? `<span class="machine-quote mq-done">Quoted</span>`
               : "";
    return `
      <button type="button" class="machine-btn ${worked ? "machine-btn-worked" : ""}" data-machine="${m.id}">
        <div class="machine-btn-top">
          <strong>${escapeHtml(m.machine_desc)}</strong>
          ${qTag || (worked ? `<span class="machine-tick">✓</span>` : `<span class="machine-untouched">Need Repair</span>`)}
        </div>
        <div class="machine-btn-sub">${m.serial_no ? "S/N " + escapeHtml(m.serial_no) + " · " : ""}${parts.length} part${parts.length === 1 ? "" : "s"}${hasComment ? " · has comment" : ""}${total > 0 ? " · " + money(total) : ""}</div>
      </button>`;
  }).join("");
  $("sd-machines").querySelectorAll(".machine-btn").forEach((btn) =>
    btn.addEventListener("click", () => openMachineModal(Number(btn.dataset.machine)))
  );

  renderSlipStatusUI();
  updateSlipFooter();
}

// ---- Machine modal ----------------------------------------------------------
function openMachineModal(machineId) {
  session.machineId = machineId;
  session.pendingParts = [];

  // Whoever opens the machine is the person working on it, so there is nothing
  // to ask. Technicians keep their long-standing codes; anyone else is recorded
  // by their initials.
  const me = getUser();
  session.technician = initialsFor(me);
  $("os-tech").value = session.technician;
  $("os-tech-field").style.display = "none";
  $("os-entry").style.display = "none";
  const m = currentMachine();
  $("mm-title").textContent = m ? m.machine_desc : "Machine";
  $("mm-sub").textContent = `Slip ${session.slipNumber} · ${session.slip.company}`;
  loadCommentForCurrentMachine();
  loadLabourForCurrentMachine();
  renderMachineParts();
  renderMachineQuoteRow();
  updateSlipFooter();
  $("machine-modal").style.display = "flex";
  document.body.style.overflow = "hidden";
  // With the technician already known there is nothing left to wait for, so
  // open straight onto the part entry instead of a panel nobody has to fill in.
  maybeShowEntry();
}

async function closeMachineModal(save) {
  if (!save && session.pendingParts.length) {
    const ok = confirm(`${session.pendingParts.length} scanned part(s) haven't been saved. Discard them?`);
    if (!ok) return;
  }
  try { stopQrScanner(); } catch (_) {}
  if (save) {
    $("mm-save").disabled = true;
    try {
      await commitPendingParts();
      await saveCurrentLabour();
      await saveCurrentComment();
      toast("Saved", "ok");
    } catch (e) {
      toast(e.message, "err");
      $("mm-save").disabled = false;
      return; // keep the modal open so nothing scanned is lost
    }
    $("mm-save").disabled = false;
  }
  $("machine-modal").style.display = "none";
  document.body.style.overflow = "";
  session.machineId = null;
  session.pendingParts = [];
  // Refresh the slip so the machine buttons reflect the latest state.
  try { await refreshSlip(); } catch (_) {}
  renderSlipScreen();
}
// Labour feeds the machine total, so recompute as it is typed.
$("os-labour").addEventListener("input", () => updateSlipFooter());

$("mm-save").addEventListener("click", () => closeMachineModal(true));
$("mm-close").addEventListener("click", () => closeMachineModal(false));

// POST every pending part to the server, in order. Stops on first failure
// (already-saved ones are removed from the pending list as they succeed).
async function commitPendingParts() {
  while (session.pendingParts.length) {
    const p = session.pendingParts[0];
    await api(`/api/machines/${session.machineId}/parts`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        item_code: p.item_code, description: p.description, uom: p.uom,
        unit_price: p.unit_price, quantity: p.quantity, technician: p.technician,
      }),
    });
    session.pendingParts.shift();
  }
}

// Load the saved comment for the currently selected machine into the textbox.
function loadCommentForCurrentMachine() {
  const box = $("os-comment");
  if (!box) return;
  const m = currentMachine();
  box.value = (m && m.repair_comment) ? m.repair_comment : "";
}

function loadLabourForCurrentMachine() {
  const box = $("os-labour");
  if (!box) return;
  const m = currentMachine();
  const v = m ? Number(m.labour_charge) || 0 : 0;
  box.value = v ? v.toFixed(2) : "";
}

// Labour typed into the box, as a number. Blank means zero.
function currentLabourValue() {
  const box = $("os-labour");
  if (!box) return 0;
  const v = parseFloat(box.value);
  return Number.isFinite(v) && v > 0 ? Math.round(v * 100) / 100 : 0;
}

// Save the labour charge for the currently selected machine.
async function saveCurrentLabour() {
  const box = $("os-labour");
  if (!box || !session.machineId) return;
  const m = currentMachine();
  const value = currentLabourValue();
  if (m && (Number(m.labour_charge) || 0) === value) return;   // unchanged
  await api(`/api/machines/${session.machineId}/labour`, {
    method: "PATCH",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ labour_charge: value }),
  });
  if (m) m.labour_charge = value;
}

// Save the textbox comment to whichever machine is currently selected.
async function saveCurrentComment() {
  const box = $("os-comment");
  if (!box || !session.machineId) return;
  const m = currentMachine();
  const current = box.value;
  // Skip the network call if nothing changed.
  if (m && (m.repair_comment || "") === current) return;
  try {
    await api(`/api/machines/${session.machineId}/comment`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ comment: current }),
    });
    if (m) m.repair_comment = current; // keep local copy in sync
  } catch (e) {
    toast("Couldn't save comment: " + e.message, "err");
  }
}

// Parts are stored against the initials (WJ, XL, KM, R) so old and new records
// agree, but there is no reason to show someone a code for their own name.
function technicianLabel() {
  const me = getUser();
  if (me && initialsFor(me) === session.technician) return me.name;
  const other = STAFF.find((u) => initialsFor(u) === session.technician);
  return other ? other.name : session.technician;
}

function onTechChosen(tech) {
  session.technician = tech || "";
  maybeShowEntry();
}

function maybeShowEntry() {
  const ready = session.slipNumber && session.machineId && session.technician;
  $("os-entry").style.display = ready ? "block" : "none";
  if (ready) {
    setMode(currentMode || "qr");
    renderContext();
    renderMachineParts();
    updateSlipFooter();
  }
}

function renderContext() {
  const m = session.slip.machines.find((x) => x.id === session.machineId);
  const created = formatDate(session.slip.created_at);
  $("os-context").innerHTML =
    `<div><strong>${escapeHtml(session.slip.company)}</strong> · Slip ${escapeHtml(session.slipNumber)}</div>` +
    `<div class="sub">Machine: ${escapeHtml(m ? m.machine_desc : "")} · Tech: ${escapeHtml(technicianLabel())}</div>` +
    (created ? `<div class="sub">Created: ${escapeHtml(created)}</div>` : "");
}

// The scanned-part entry point. Parts are held as PENDING (not yet saved) and
// committed to the server when the technician taps Save in the machine popup.
async function addByCode(code) {
  code = (code || "").trim();
  if (!code) return;
  if (!session.machineId || !session.technician) {
    toast("Pick your name first", "err");
    return;
  }
  try {
    const item = await lookupItem(code);
    // Same part already pending for this tech? Just bump its quantity.
    const existing = session.pendingParts.find(
      (p) => p.item_code === item.item_code && p.technician === session.technician
    );
    if (existing) {
      existing.quantity += 1;
    } else {
      let description = item.description;
      // The moment to name one of these is now, while the part is in hand -
      // not later from a list of identical "SPARE PARTS" lines.
      if (isFreeTextPart(item.item_code)) {
        const typed = prompt(
          `${item.item_code}

What is this part? It will appear on the Sales Order.`,
          ""
        );
        if (typed === null) return;                  // changed their mind
        if (typed.trim()) description = typed.trim();
      }
      session.pendingParts.push({
        item_code: item.item_code,
        description,
        uom: item.uom,
        unit_price: item.unit_price,
        quantity: 1,
        technician: session.technician,
      });
      toast(`Added ${description} — tap Save when done`, "ok");
      renderMachineParts();
      updateSlipFooter();
      return;
    }
    toast(`Added ${item.description} — tap Save when done`, "ok");
    renderMachineParts();
    updateSlipFooter();
  } catch (e) {
    toast(e.message, "err");
  }
}

async function refreshSlip() {
  if (!session.slipNumber) return;
  // Preserve whatever the technician has typed in the comment box for the
  // current machine, so a part-scan refresh doesn't wipe an unsaved comment.
  const box = $("os-comment");
  const unsaved = (box && session.machineId) ? box.value : null;

  session.slip = await api(`/api/slips/${encodeURIComponent(session.slipNumber)}`);

  if (unsaved !== null) {
    const m = currentMachine();
    if (m) m.repair_comment = unsaved; // keep local copy aligned with the box
  }
}

const PENCIL = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 17.5 17.5 3a2.1 2.1 0 0 1 3 3L6 20.5 2 21z"/></svg>';
const TRASH = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 6h18M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2m2 0v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6"/><path d="M10 11v6M14 11v6"/></svg>';

function currentMachine() {
  if (!session.slip) return null;
  return session.slip.machines.find((m) => m.id === session.machineId) || null;
}

// The A5-A8 and MISC codes stand in for something not really in the catalogue.
// The code is right for the accounts; what the part actually was is only known
// to whoever is holding it.
function isFreeTextPart(itemCode) {
  const code = String(itemCode || "").trim().toUpperCase();
  return /^A[5-8]\b/.test(code) || code.startsWith("MISC");
}

async function editPartDescription(partId, current) {
  const text = prompt("What is this part? It will appear on the Sales Order.", current || "");
  if (text === null) return;
  const clean = text.trim();
  if (!clean) { toast("A description is required.", "err"); return; }
  try {
    await api(`/api/parts/${partId}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ description: clean }),
    });
    await refreshSlip();
    renderMachineParts();
  } catch (e) {
    toast(e.message, "err");
  }
}

function renderMachineParts() {
  const wrap = $("machine-parts");
  const machine = currentMachine();
  const parts = machine ? (machine.parts || []) : [];
  wrap.innerHTML = "";

  // Pending (scanned but not yet saved) parts first, visually distinct.
  if (session.pendingParts.length) {
    const pendWrap = document.createElement("div");
    pendWrap.className = "pending-wrap";
    pendWrap.innerHTML = `<div class="pending-head">Not saved yet — tap Save below</div>` +
      session.pendingParts.map((p, i) => `
        <div class="line line-pending">
          <div class="head">
            <div class="info">
              <div class="desc">${escapeHtml(p.description)}</div>
              <div class="sku mono">${escapeHtml(p.item_code)} · ${escapeHtml(p.technician)}</div>
            </div>
            <div class="price-col">
              <span class="price-edit">$<input type="number" step="0.01" min="0" value="${Number(p.unit_price).toFixed(2)}" data-pprice="${i}" inputmode="decimal" aria-label="Unit price" /></span>
              <button class="remove" data-pdel="${i}" aria-label="Remove part">${TRASH}</button>
            </div>
          </div>
          <div class="foot">
            <div class="qty">
              <button data-pdec="${i}" aria-label="Decrease">−</button>
              <input type="number" min="1" value="${p.quantity}" data-pqty="${i}" inputmode="numeric" aria-label="Quantity" />
              <button data-pinc="${i}" aria-label="Increase">+</button>
            </div>
            <div class="amt-wrap">
              <span class="amt-lbl">Line total</span>
              <span class="amt">${money(p.unit_price * p.quantity)}</span>
            </div>
          </div>
        </div>`).join("");
    wrap.appendChild(pendWrap);
  }

  if (parts.length === 0 && session.pendingParts.length === 0) {
    wrap.innerHTML = `
      <div class="cart-empty">
        <div class="ico">
          <svg viewBox="0 0 24 24" fill="none" stroke="#1f6f78" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><circle cx="9" cy="21" r="1"/><circle cx="20" cy="21" r="1"/><path d="M1 1h4l2.7 13.4a2 2 0 0 0 2 1.6h9.7a2 2 0 0 0 2-1.6L23 6H6"/></svg>
        </div>
        <strong>No parts yet</strong>
        <span>Scan or type a part to add it to this machine.</span>
      </div>`;
    return;
  }

  for (const p of parts) {
    const noPrice = !(Number(p.unit_price) > 0);
    const el = document.createElement("div");
    el.className = "line" + (noPrice ? " no-price" : "");
    el.innerHTML = `
      <div class="head">
        <div class="info">
          <div class="desc">${escapeHtml(p.description)}${
            isFreeTextPart(p.item_code)
              ? ` <button type="button" class="desc-edit" data-desc="${p.id}" aria-label="Edit description">${PENCIL}</button>`
              : ""
          }</div>
          <div class="sku mono">${escapeHtml(p.item_code)} · ${escapeHtml(p.technician || "")}</div>
          ${noPrice ? `<div class="no-price-tag">No price — enter one</div>` : ""}
        </div>
        <div class="price-col">
          <span class="price-edit">$<input type="number" step="0.01" min="0" value="${Number(p.unit_price).toFixed(2)}" data-price="${p.id}" inputmode="decimal" aria-label="Unit price" /></span>
          <button class="remove" data-del="${p.id}" aria-label="Remove part">${TRASH}</button>
        </div>
      </div>
      <div class="foot">
        <div class="qty">
          <button data-dec="${p.id}" aria-label="Decrease">−</button>
          <input type="number" min="1" value="${p.quantity}" data-qty="${p.id}" inputmode="numeric" aria-label="Quantity" />
          <button data-inc="${p.id}" aria-label="Increase">+</button>
        </div>
        <div class="amt-wrap">
          <span class="amt-lbl">Line total</span>
          <span class="amt">${money(p.unit_price * p.quantity)}</span>
        </div>
      </div>`;
    wrap.appendChild(el);
  }
}

async function setPartPrice(partId, price) {
  try {
    await api(`/api/parts/${partId}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ unit_price: price }),
    });
    await refreshSlip();
    renderMachineParts();
    updateSlipFooter();
  } catch (e) {
    toast(e.message, "err");
  }
}

async function setPartQty(partId, qty) {
  try {
    await api(`/api/parts/${partId}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ quantity: qty }),
    });
    await refreshSlip();
    renderMachineParts();
    updateSlipFooter();
  } catch (e) {
    toast(e.message, "err");
  }
}

function updateSlipFooter() {
  if (!session.slip) return;

  // Slip summary (on the slip-detail screen): number, machine count, slip total
  $("os-slip-badge").textContent = session.slipNumber || "—";
  const machines = session.slip.machines || [];
  let slipTotal = 0, slipParts = 0;
  for (const m of machines) {
    for (const p of (m.parts || [])) { slipTotal += p.unit_price * p.quantity; slipParts++; }
    slipTotal += Number(m.labour_charge) || 0;
  }
  $("os-machine-name").textContent = `${machines.length} machine${machines.length === 1 ? "" : "s"}`;
  $("os-machine-total").textContent = money(slipTotal);

  // Status badge + which status action buttons apply right now
  renderSlipStatusUI();

  // Machine total inside the modal: saved parts + pending (unsaved) parts
  const machine = currentMachine();
  if (machine) {
    let mt = 0;
    for (const p of (machine.parts || [])) mt += p.unit_price * p.quantity;
    for (const p of session.pendingParts) mt += p.unit_price * p.quantity;
    // Reads the box, not the saved value, so the total moves as it is typed.
    mt += currentLabourValue();
    const mmTotal = $("mm-total");
    if (mmTotal) mmTotal.textContent = money(mt);
  }

  // Create Sales Order covers the whole slip; enable when parts exist and the
  // slip hasn't already been repaired/closed.
  // Billable when there is anything to charge for — parts OR labour. A slip
  // that is pure labour ("cleaned the carburettor, no parts") is legitimate.
  const st = session.slip.status;
  const billable = slipParts > 0 || slipTotal > 0;
  // A slip converted machine by machine sits at ALL_REPAIRED between orders, so
  // that status must not disable the button any more - only a slip whose every
  // machine is already on an order, or one that is closed.
  renderAutoCountPending();
  const machinesLeft = (session.slip && (session.slip.machines || []).some((m) => !m.converted_at));
  $("os-create-so").disabled = !billable || !machinesLeft || st === "CLOSED" || st === "CONVERTED";
}

// ---- Quoting one machine ----------------------------------------------------
// A technician who has finished one machine on a two-machine slip can hand that
// one over to be priced without claiming the other is done. The slip's own
// buttons still cover "all of them together".
function renderMachineQuoteRow() {
  const row = $("mm-quote-row");
  if (!row) return;
  const m = currentMachine();
  const slipStatus = session.slip ? session.slip.status : "";
  // Once a slip is fully repaired, converted or closed it has left quoting
  // behind, and the buttons would only offer a state it cannot go back to.
  const live = slipStatus === "OPEN" || slipStatus === "IN_PROGRESS" ||
               slipStatus === "NEED_QUOTE" || slipStatus === "QUOTED";
  if (!m || !live) { row.style.display = "none"; return; }

  const q = m.quote_status || "";
  const state = $("mm-quote-state");
  const btn = $("mm-quote-btn");
  row.style.display = "flex";

  if (q === "NEED_QUOTE") {
    state.innerHTML = `<span class="machine-quote mq-need">Waiting to quote</span> Sales have been told about this machine.`;
    btn.textContent = "Undo — still repairing";
    btn.dataset.next = "";
  } else if (q === "QUOTED") {
    state.innerHTML = `<span class="machine-quote mq-done">Quoted</span> Already sent to the customer.`;
    btn.textContent = "Send for quoting again";
    btn.dataset.next = "NEED_QUOTE";
  } else {
    state.textContent = "This machine has not been sent for quoting.";
    btn.textContent = "Send this machine for quoting";
    btn.dataset.next = "NEED_QUOTE";
  }
}

$("mm-quote-btn").addEventListener("click", async () => {
  const m = currentMachine();
  if (!m || !session.slipNumber) return;
  const next = $("mm-quote-btn").dataset.next || "";

  // Anything scanned but not yet saved would otherwise be missing from the very
  // quote this is asking for.
  if (next === "NEED_QUOTE" && session.pendingParts.length) {
    try {
      await commitPendingParts();
      await saveCurrentLabour();
      await saveCurrentComment();
    } catch (e) { toast(e.message, "err"); return; }
  }

  const btn = $("mm-quote-btn");
  btn.disabled = true;
  try {
    await api(`/api/slips/${encodeURIComponent(session.slipNumber)}/machines/${m.id}/quote`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ quote_status: next }),
    });
    await refreshSlip();
    renderMachineParts();
    renderMachineQuoteRow();
    updateSlipFooter();
    toast(next === "NEED_QUOTE" ? "Sent for quoting" : "Taken back", "ok");
  } catch (e) {
    toast(e.message, "err");
  }
  btn.disabled = false;
});

// ---- Slip status UI (Open Service) ------------------------------------------
// Shows the current status as a badge next to the slip number, and decides
// which manual status buttons apply:
//   OPEN / IN_PROGRESS  -> [Need to Quote] [Close w/o Quote]
//   NEED_QUOTE          -> [Mark as Quoted] [Close w/o Quote]
//   QUOTED              -> [Close w/o Quote]  (returns to In Progress)
//   ALL_REPAIRED/CLOSED -> no buttons
function renderSlipStatusUI() {
  const status = session.slip ? session.slip.status : "";
  const badge = $("os-status-badge");
  if (badge) {
    badge.textContent = STATUS_LABEL[status] || status || "—";
    badge.className = "vs-status vs-" + status;
  }
  const wrap = $("os-status-actions");
  if (!wrap) return;
  const machines = (session.slip && session.slip.machines) || [];
  const live = status === "OPEN" || status === "IN_PROGRESS" ||
               status === "NEED_QUOTE" || status === "QUOTED";
  // Machines can now be sent for quoting one at a time, so this button is the
  // "all of them together" case: offered while any machine is still not
  // waiting, including on a slip already part-way through quoting.
  const someLeft = machines.some((m) => (m.quote_status || "") !== "NEED_QUOTE");
  const showQuote = live && someLeft;
  const showQuoted = status === "NEED_QUOTE";
  const showNoQuote = live;
  const quoteBtn = $("os-need-quote");
  quoteBtn.textContent = machines.length > 1
    ? (status === "NEED_QUOTE" ? "Quote the rest too" : "Quote all machines")
    : "Need to Quote";
  quoteBtn.style.display = showQuote ? "inline-flex" : "none";
  $("os-mark-quoted").style.display = showQuoted ? "inline-flex" : "none";
  $("os-no-quote").style.display = showNoQuote ? "inline-flex" : "none";
  wrap.style.display = (showQuote || showQuoted || showNoQuote) ? "flex" : "none";
}

async function changeSlipStatus(newStatus, confirmMsg) {
  if (!session.slipNumber) return;
  try {
    await api(`/api/slips/${encodeURIComponent(session.slipNumber)}/status`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ status: newStatus }),
    });
    await refreshSlip();
    updateSlipFooter();
    toast(confirmMsg, "ok");
  } catch (e) {
    toast(e.message, "err");
  }
}

$("os-need-quote").addEventListener("click", () => changeSlipStatus("NEED_QUOTE", "Marked: Need to Quote"));
$("os-mark-quoted").addEventListener("click", () => changeSlipStatus("QUOTED", "Marked: Quoted"));
$("os-no-quote").addEventListener("click", () => {
  const s = session.slip ? session.slip.status : "";
  if (s === "NEED_QUOTE" || s === "QUOTED") {
    changeSlipStatus("IN_PROGRESS", "Continuing without quote");
  } else {
    toast("No quote needed — carry on", "ok");
  }
});

// An order that did not reach AutoCount must not sit unnoticed. The toast that
// reported it lasts four seconds; this stays until the order is sent.
async function renderAutoCountPending() {
  const box = $("os-ac-pending");
  if (!box || !session.slip) return;
  let waiting = [];
  try {
    const r = await api("/api/orders/awaiting-autocount");
    const mine = `S/S: ${session.slip.slip_number}`;
    waiting = (r.orders || []).filter((o) => o.notes === mine);
  } catch (_) {
    box.style.display = "none";
    return;
  }
  if (!waiting.length) { box.style.display = "none"; box.innerHTML = ""; return; }

  box.style.display = "block";
  box.innerHTML = waiting.map((o) => `
    <div class="ac-pending-row" data-so="${escapeAttr(o.so_number)}">
      <div class="ac-pending-main">
        <strong>${escapeHtml(o.so_number)} is not in AutoCount</strong>
        <span>${escapeHtml(o.autocount_error || "It has not been sent yet.")}</span>
      </div>
      <button type="button" class="ac-retry" data-retry="${escapeAttr(o.so_number)}">Send to AutoCount</button>
    </div>`).join("");

  box.querySelectorAll(".ac-retry").forEach((b) =>
    b.addEventListener("click", async () => {
      b.disabled = true;
      const was = b.textContent;
      b.textContent = "Sending…";
      try {
        const r = await api(`/api/orders/${encodeURIComponent(b.dataset.retry)}/push-to-autocount`, { method: "POST" });
        if (r.pushed) toast(`Written into AutoCount as ${r.doc_no}`, "ok");
        else toast(r.reason || "Still could not write it.", "err");
      } catch (e) {
        toast(e.message, "err");
      }
      b.disabled = false;
      b.textContent = was;
      await refreshSlip();
      renderAutoCountPending();
    })
  );
}

// Ask which machines go on this order. A slip is converted a machine at a
// time, so this is the normal case rather than a special one.
function openConvertPicker() {
  if (!session.slip) return;
  const machines = session.slip.machines || [];
  const left = machines.filter((m) => !m.converted_at);
  if (!left.length) {
    toast("Every machine on this slip is already on a Sales Order.", "ok");
    return;
  }
  $("conv-sub").textContent = `Slip ${session.slip.slip_number} · ${session.slip.company}`;
  $("conv-status").innerHTML = "";
  // Reset here rather than on each exit path: a slip is converted several
  // times over, and a button left disabled by the previous run is silent -
  // the click simply does nothing and nobody can tell why.
  $("conv-go").disabled = false;
  $("conv-list").innerHTML = machines.map((m) => {
    const done = !!m.converted_at;
    const parts = (m.parts || []).length;
    const labour = Number(m.labour_charge) || 0;
    const billable = parts > 0 || labour > 0 || String(m.repair_comment || "").trim();
    const sub = done
      ? `On ${escapeHtml(m.so_number || "a Sales Order")}`
      : billable
        ? `${parts} part${parts === 1 ? "" : "s"}${labour > 0 ? " · labour " + money(labour) : ""}`
        : "No work recorded yet";
    return `
      <label class="conv-row${done ? " conv-done" : ""}${!done && !billable ? " conv-blocked" : ""}">
        <input type="checkbox" value="${m.id}" ${done || !billable ? "disabled" : "checked"}>
        <span class="conv-main">
          <span class="conv-name">${escapeHtml(m.machine_desc)}</span>
          ${m.serial_no ? `<span class="conv-serial">S/N ${escapeHtml(m.serial_no)}</span>` : ""}
          <span class="conv-sub">${sub}</span>
        </span>
      </label>`;
  }).join("");
  $("conv-modal").style.display = "flex";
  document.body.style.overflow = "hidden";
}

function closeConvertPicker() {
  $("conv-modal").style.display = "none";
  document.body.style.overflow = "";
}

async function createSalesOrder() {
  if (!session.slipNumber) return;
  const chosen = [...document.querySelectorAll("#conv-list input:checked")].map((c) => Number(c.value));
  if (!chosen.length) {
    $("conv-status").innerHTML = statusErr("Pick at least one machine.");
    return;
  }
  $("conv-go").disabled = true;
  $("os-create-so").disabled = true;
  // Persist the current machine's comment first (per the agreed save-on-SO behaviour).
  await saveCurrentComment();
  try {
    const result = await api(`/api/slips/${encodeURIComponent(session.slipNumber)}/order`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ machine_ids: chosen }),
    });
    closeConvertPicker();

    // Say plainly whether it reached AutoCount. A silent failure here is the
    // worst outcome: staff would believe the order exists and only find out
    // when they went looking for it.
    const ac = result.autocount || {};
    if (ac.pushed) {
      // The app has taken AutoCount's number, so there is only one to report.
      setTimeout(() => toast(
        ac.rename_note
          ? `In AutoCount as ${ac.doc_no} (the app kept ${result.so_number}: ${ac.rename_note})`
          : `Written into AutoCount as Sales Order ${ac.doc_no}`,
        ac.rename_note ? "err" : "ok"), 1600);
    } else if (ac.error) {
      setTimeout(() => toast(`NOT written to AutoCount: ${ac.error}`, "err"), 1600);
    } else if (ac.reason && !/switched off|not enabled/i.test(ac.reason)) {
      setTimeout(() => toast(`Not written to AutoCount: ${ac.reason}`, "err"), 1600);
    }

    const left = result.machines_remaining;
    toast(
      left === 0
        ? `Sales Order ${result.so_number} created — slip is now Converted`
        : `Sales Order ${result.so_number} created — ${left} machine${left === 1 ? "" : "s"} still to convert`,
      "ok"
    );
    // Straight into the keyable block — this is the moment it gets typed into
    // AutoCount, so don't make anyone go looking for it.
    showSlipOrder(session.slipNumber);
    // Report price write-back outcome (prices saved into AutoCount for parts
    // that previously had none). Failures are non-blocking but flagged.
    const ps = result.price_sync;
    if (ps && ps.failed && ps.failed.length) {
      setTimeout(() => toast(`Price save to AutoCount failed for: ${ps.failed.join(", ")}`, "err"), 1800);
      setTimeout(async () => { await refreshSlip(); renderSlipScreen(); }, 4200);
    } else if (ps && ps.updated && ps.updated.length) {
      setTimeout(() => toast(`${ps.updated.length} price${ps.updated.length === 1 ? "" : "s"} saved to AutoCount`, "ok"), 1800);
      setTimeout(async () => { await refreshSlip(); renderSlipScreen(); }, 3600);
    } else {
      setTimeout(async () => { await refreshSlip(); renderSlipScreen(); }, 1600);
    }
  } catch (e) {
    toast(e.message, "err");
    $("os-create-so").disabled = false;
    $("conv-go").disabled = false;
  }
}

// ============================================================================
// CLOSE SERVICE
// ============================================================================
let closeSearch = null;
let csPickedSlip = null; // currently selected slip number in Close Service
async function enterCloseService() {
  showScreen("close");
  $("cs-context").style.display = "none";
  $("cs-ref").value = "";
  $("cs-status").innerHTML = "";
  csPickedSlip = null;

  if (!closeSearch) {
    closeSearch = setupSlipSearch({
      inputId: "cs-search", resultsId: "cs-results", scope: "repaired",
      onPick: (slipNumber) => onCloseSlipChosen(slipNumber),
    });
  }
  closeSearch.reset();
}

async function onCloseSlipChosen(slipNumber) {
  csPickedSlip = slipNumber || null;
  if (!slipNumber) { $("cs-context").style.display = "none"; return; }
  try {
    const slip = await api(`/api/slips/${encodeURIComponent(slipNumber)}`);
    $("cs-context").style.display = "block";
    $("cs-context").innerHTML =
      `<div><strong>${escapeHtml(slip.company)}</strong> · Slip ${escapeHtml(slip.slip_number)}</div>` +
      `<div class="sub">Status: ${escapeHtml(slip.status)} · ${slip.machines.length} machine(s)</div>` +
      (formatDate(slip.created_at) ? `<div class="sub">Created: ${escapeHtml(formatDate(slip.created_at))}</div>` : "");
  } catch (e) {
    toast(e.message, "err");
  }
}

async function submitClose() {
  const slipNumber = csPickedSlip;
  const ref = $("cs-ref").value.trim();
  if (!slipNumber) { $("cs-status").innerHTML = statusErr("Pick a slip to close."); return; }
  if (!ref) { $("cs-status").innerHTML = statusErr("Enter the DO/CS/INV number."); return; }

  $("cs-submit").disabled = true;
  $("cs-status").innerHTML = statusInfo("Closing…");
  try {
    await api(`/api/slips/${encodeURIComponent(slipNumber)}/close`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ closing_ref: ref }),
    });
    toast(`Slip ${slipNumber} closed`, "ok");
    $("cs-status").innerHTML = statusOk(`Closed ${slipNumber}. Returning home…`);
    setTimeout(goHome, 1400);
  } catch (e) {
    $("cs-status").innerHTML = statusErr(e.message);
  } finally {
    $("cs-submit").disabled = false;
  }
}

// ============================================================================
// VIEW SLIPS (read-only)
// ============================================================================
let viewSearch = null;
async function enterViewSlips() {
  showScreen("view");
  $("vs-detail").innerHTML = "";
  if (!viewSearch) {
    viewSearch = setupSlipSearch({
      inputId: "vs-search", resultsId: "vs-results", scope: "all",
      onPick: (slipNumber) => onViewSlipChosen(slipNumber),
    });
  }
  viewSearch.reset();
}

async function onViewSlipChosen(slipNumber) {
  const wrap = $("vs-detail");
  if (!slipNumber) { wrap.innerHTML = ""; return; }
  wrap.innerHTML = `<div class="slip-context"><span class="led"></span> Loading…</div>`;
  try {
    const slip = await api(`/api/slips/${encodeURIComponent(slipNumber)}`);
    wrap.innerHTML = renderSlipDetail(slip);
    wireVsStatusActions(slipNumber);
    // Rebuilt from the stored slip, so a re-issued copy matches the original.
    const share = document.getElementById("vs-share");
    if (share) share.addEventListener("click", () => shareSlipPdf(slip));
    if (share) {
      whatsappStatus().then((wa) => {
        if (!wa.enabled || !wa.configured) return;
        const btn = document.createElement("button");
        btn.className = "btn-secondary wa-send";
        btn.type = "button";
        btn.style.cssText = "width:100%;margin-top:8px;";
        btn.textContent = "Send to customer on WhatsApp";
        share.insertAdjacentElement("afterend", btn);
        // Never automatic here - this screen is opened to look at old slips,
        // and re-sending one just because it was viewed would be alarming.
        wireWhatsappButton(btn, slip, { auto: false });
      });
    }
    const soBtn = document.getElementById("vs-so");
    if (soBtn) soBtn.addEventListener("click", () => showSlipOrder(slip.slip_number));
  } catch (e) {
    wrap.innerHTML = "";
    toast(e.message, "err");
  }
}

// The same manual status buttons as Open Service, rendered in the View Slips
// detail so sales can manage quoting from here too.
function renderVsStatusActions(slip) {
  const s = slip.status;
  const showQuote = s === "OPEN" || s === "IN_PROGRESS";
  const showQuoted = s === "NEED_QUOTE";
  const showNoQuote = showQuote || showQuoted || s === "QUOTED";
  if (!showQuote && !showQuoted && !showNoQuote) return "";
  return `<div class="status-actions">
    ${showQuote ? `<button class="status-btn status-btn-quote" data-vs-status="NEED_QUOTE">Need to Quote</button>` : ""}
    ${showQuoted ? `<button class="status-btn status-btn-quoted" data-vs-status="QUOTED">Mark as Quoted</button>` : ""}
    ${showNoQuote ? `<button class="status-btn status-btn-noquote" data-vs-status="NO_QUOTE">Close w/o Quote</button>` : ""}
  </div>`;
}

function wireVsStatusActions(slipNumber) {
  document.querySelectorAll("#vs-detail [data-vs-status]").forEach((btn) =>
    btn.addEventListener("click", async () => {
      const action = btn.dataset.vsStatus;
      try {
        if (action === "NO_QUOTE") {
          // Only meaningful when currently in a quoting state; otherwise confirm.
          const slip = await api(`/api/slips/${encodeURIComponent(slipNumber)}`);
          if (slip.status === "NEED_QUOTE" || slip.status === "QUOTED") {
            await api(`/api/slips/${encodeURIComponent(slipNumber)}/status`, {
              method: "PATCH",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify({ status: "IN_PROGRESS" }),
            });
            toast("Continuing without quote", "ok");
          } else {
            toast("No quote needed — carry on", "ok");
          }
        } else {
          await api(`/api/slips/${encodeURIComponent(slipNumber)}/status`, {
            method: "PATCH",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ status: action }),
          });
          toast(action === "NEED_QUOTE" ? "Marked: Need to Quote" : "Marked: Quoted", "ok");
        }
        onViewSlipChosen(slipNumber); // re-render with the new status
      } catch (e) {
        toast(e.message, "err");
      }
    })
  );
}

function renderSlipDetail(slip) {
  // Header block: customer + meta
  let slipQty = 0, slipAmount = 0, slipParts = 0, slipLabour = 0;
  for (const m of slip.machines) {
    for (const p of (m.parts || [])) { slipQty += p.quantity; slipAmount += p.unit_price * p.quantity; slipParts++; }
    slipLabour += Number(m.labour_charge) || 0;
  }
  slipAmount += slipLabour;

  const meta = [];
  if (slip.contact_name) meta.push(`Contact: ${escapeHtml(slip.contact_name)}`);
  if (slip.contact_number) meta.push(escapeHtml(slip.contact_number));

  let html = `
    <div class="vs-card">
      <div class="vs-head">
        <div>
          <div class="vs-company">${escapeHtml(slip.company)}</div>
          <div class="vs-sub">Slip ${escapeHtml(slip.slip_number)} · Created ${escapeHtml(formatDate(slip.created_at))}</div>
        </div>
        <span class="vs-status vs-${escapeAttr(slip.status)}">${escapeHtml(STATUS_LABEL[slip.status] || slip.status)}</span>
      </div>
      ${meta.length ? `<div class="vs-sub">${meta.join(" · ")}</div>` : ""}
      ${(slip.check_service || slip.quote_first) ? `<div class="vs-requests">${slip.check_service ? `<span class="vs-req-badge">Check &amp; Service for all</span>` : ""}${slip.quote_first ? `<span class="vs-req-badge">Quote first</span>` : ""}</div>` : ""}
      ${slip.notes ? `<div class="vs-notes">${escapeHtml(slip.notes)}</div>` : ""}
      ${slip.status === "CLOSED" && slip.closing_ref ? `<div class="vs-sub">Closed with: <strong>${escapeHtml(slip.closing_ref)}</strong>${slip.closed_at ? " on " + escapeHtml(formatDate(slip.closed_at)) : ""}</div>` : ""}
      ${renderVsStatusActions(slip)}
    </div>`;

  // Each machine + its parts
  for (const m of slip.machines) {
    const parts = m.parts || [];
    const mLabour = Number(m.labour_charge) || 0;
    let mQty = 0, mAmount = 0;
    for (const p of parts) { mQty += p.quantity; mAmount += p.unit_price * p.quantity; }
    mAmount += mLabour;

    html += `
      <div class="vs-machine">
        <div class="vs-machine-name">${escapeHtml(m.machine_desc)}${
          m.quote_status === "NEED_QUOTE" ? ` <span class="machine-quote mq-need">Waiting to quote</span>`
        : m.quote_status === "QUOTED"     ? ` <span class="machine-quote mq-done">Quoted</span>` : ""}</div>
        ${m.serial_no ? `<div class="vs-machine-serial">S/N ${escapeHtml(m.serial_no)}</div>` : ""}`;

    if (m.repair_comment) {
      html += `<div class="vs-comment">${escapeHtml(m.repair_comment)}</div>`;
    }

    if (parts.length === 0 && !mLabour) {
      html += `<div class="vs-sub" style="padding:6px 0;">No parts recorded.</div>`;
    } else {
      if (parts.length === 0) {
        html += `<div class="vs-sub" style="padding:6px 0;">No parts recorded.</div>`;
      }
      for (const p of parts) {
        html += `
          <div class="vs-part">
            <div class="vs-part-info">
              <div class="vs-part-desc">${escapeHtml(p.description)}</div>
              <div class="vs-part-sku mono">${escapeHtml(p.item_code)}${p.technician ? " · " + escapeHtml(p.technician) : ""}</div>
            </div>
            <div class="vs-part-amt">
              <div>${escapeHtml(String(p.quantity))} × ${money(p.unit_price)}</div>
              <div class="vs-part-line">${money(p.unit_price * p.quantity)}</div>
            </div>
          </div>`;
      }
      if (mLabour) {
        html += `
          <div class="vs-part">
            <div class="vs-part-info">
              <div class="vs-part-desc">Labour Charge</div>
            </div>
            <div class="vs-part-amt">
              <div class="vs-part-line">${money(mLabour)}</div>
            </div>
          </div>`;
      }
      html += `<div class="vs-machine-total">Machine total: <strong>${money(mAmount)}</strong> (${mQty} qty)</div>`;
    }
    html += `</div>`;
  }

  // Slip total
  html += `
    <div class="vs-grand">
      <span>${slipParts} part${slipParts === 1 ? "" : "s"} · ${slipQty} qty across ${slip.machines.length} machine${slip.machines.length === 1 ? "" : "s"}${slipLabour ? ` · incl. ${money(slipLabour)} labour` : ""}</span>
      <strong>${money(slipAmount)}</strong>
    </div>`;

  // Re-issue the customer's copy — same PDF as registration, signature and all.
  html += `
    <button class="btn-primary" id="vs-share" style="margin-top:14px;">Share slip (PDF)</button>`;

  // Once an order exists, the keyable AutoCount block stays reachable — sales
  // may key it in later, or need it again.
  if (slip.status === "ALL_REPAIRED" || slip.status === "CLOSED") {
    html += `
      <button class="btn-secondary" id="vs-so" style="margin-top:10px;width:100%;">View Sales Order</button>`;
  }

  return html;
}

// ---- Sales Order block ------------------------------------------------------
// Shows the order exactly as it is keyed into AutoCount: one block per machine,
// opened by the labour line, then the machine heading, its parts, the repair
// comment and a sub-total. Un-coded rows are notes and carry no price.
function renderSalesOrder(order) {
  const lines = order.lines || [];
  let html = `
    <div class="so-row so-head">
      <span>Item Code</span><span>Description</span>
      <span class="so-qty">Qty</span><span class="so-price">Price</span><span class="so-amt">Amount</span>
    </div>`;

  for (const l of lines) {
    const isNote = !l.item_code;
    let kind = "";
    if (isNote) {
      const d = String(l.description || "");
      if (d === "SubTotal") kind = " so-row-sub";
      else if (d.startsWith("*")) kind = " so-row-comment";
      else if (d.includes("S/S:")) kind = " so-row-machine";
      else kind = " so-row-note";
    }
    html += `
      <div class="so-row${isNote ? " so-row-note" : ""}${kind}">
        <span class="so-code mono">${escapeHtml(l.item_code || "")}</span>
        <span class="so-desc">${escapeHtml(l.description || "")}</span>
        <span class="so-qty">${l.quantity ? escapeHtml(String(l.quantity)) : ""}</span>
        <span class="so-price">${l.quantity ? money(l.unit_price) : ""}</span>
        <span class="so-amt">${l.line_amount ? money(l.line_amount) : ""}</span>
      </div>`;
  }

  $("so-lines").innerHTML = html;
  $("so-sub").textContent = `${order.so_number} · ${order.notes || ""}`;
  $("so-total").textContent = money(order.total_amount);
  $("so-modal").style.display = "flex";
  document.body.style.overflow = "hidden";
}

function closeSalesOrder() {
  $("so-modal").style.display = "none";
  document.body.style.overflow = "";
}
$("so-close").addEventListener("click", closeSalesOrder);
$("so-modal").addEventListener("click", (e) => {
  if (e.target === $("so-modal")) closeSalesOrder();
});

// Fetch and show the order raised for a slip.
async function showSlipOrder(slipNumber) {
  try {
    const order = await api(`/api/slips/${encodeURIComponent(slipNumber)}/order`);
    renderSalesOrder(order);
  } catch (e) {
    toast(e.message, "err");
  }
}

// ---- Scanner ---------------------------------------------------------------
function scanStatus(html) { const el = $("scan-status"); if (el) el.innerHTML = html; }

// Scanner engine: prefer the device's native BarcodeDetector (fast, accurate on
// Code 128 — great on Android), fall back to ZXing (covers iPhone Safari).
let videoStream = null;
let detectLoop = null;
let zxingReader = null;
let torchOn = false;
// Double-read confirm: hold the last candidate; only accept on a second matching read.
let pendingCode = null;

const STATUS_READY = '<span class="led"></span> Point at a barcode — tap the view to focus';
const STATUS_BLOCKED = '<span class="led" style="background:var(--amber);box-shadow:0 0 0 3px var(--amber-tint)"></span> Camera blocked — switch to Type code';

async function startScanner() {
  await stopScanner();
  const video = $("reader-video");
  if (!video) { scanStatus(STATUS_BLOCKED); return; }

  try {
    // Ask for a high-resolution rear camera with continuous autofocus tuned for
    // close-up labels — sharper frames lock far faster, especially up close.
    videoStream = await navigator.mediaDevices.getUserMedia({
      video: {
        facingMode: { ideal: "environment" },
        width: { ideal: 1920 },
        height: { ideal: 1080 },
        focusMode: { ideal: "continuous" },
        // Nudge focus toward a near distance (macro) so a close label snaps sharp
        // quickly instead of hunting across the whole range. Ignored if unsupported.
        focusDistance: { ideal: 0.12 },
        advanced: [{ focusMode: "continuous" }, { focusDistance: 0.12 }],
      },
      audio: false,
    });
    video.srcObject = videoStream;
    video.setAttribute("playsinline", "true");
    await video.play();
    scanStatus(STATUS_READY);
    updateTorchButton();
    applyFocusTuning();
  } catch (e) {
    // Retry with a basic request if the constrained one was rejected.
    try {
      videoStream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: "environment" }, audio: false,
      });
      video.srcObject = videoStream;
      video.setAttribute("playsinline", "true");
      await video.play();
      scanStatus(STATUS_READY);
      updateTorchButton();
      applyFocusTuning();
    } catch (e2) {
      scanStatus(STATUS_BLOCKED);
      return;
    }
  }

  // Path 1: native BarcodeDetector (Chrome/Android, some others)
  if ("BarcodeDetector" in window) {
    try {
      const detector = new window.BarcodeDetector({
        formats: ["code_128", "code_39", "qr_code", "ean_13"],
      });
      const tick = async () => {
        if (!videoStream) return;
        try {
          const codes = await detector.detect(video);
          if (codes && codes.length) onScanCandidate(codes[0].rawValue);
        } catch (_) {}
        detectLoop = requestAnimationFrame(tick);
      };
      detectLoop = requestAnimationFrame(tick);
      return;
    } catch (_) {
      // fall through to ZXing
    }
  }

  // Path 2: ZXing fallback (iPhone Safari, browsers without BarcodeDetector)
  if (window.ZXingBrowser) {
    try {
      zxingReader = new ZXingBrowser.BrowserMultiFormatReader();
      zxingReader.decodeFromVideoElement(video, (result) => {
        if (result) onScanCandidate(result.getText());
      });
      return;
    } catch (_) {}
  }

  // Camera works but no decoder engine is available — guide to manual entry.
  scanStatus('<span class="led" style="background:var(--amber);box-shadow:0 0 0 3px var(--amber-tint)"></span> Scanner not supported here — use Type code');
}

// Torch / flashlight — helps in dim storeroom lighting. Supported on most
// Android Chrome; quietly hidden where the device/browser can't do it.
function torchTrack() {
  if (!videoStream) return null;
  const track = videoStream.getVideoTracks()[0];
  if (!track || !track.getCapabilities) return null;
  const caps = track.getCapabilities();
  return caps && caps.torch ? track : null;
}
function updateTorchButton() {
  const btn = $("torch-btn");
  if (!btn) return;
  btn.style.display = torchTrack() ? "flex" : "none";
  btn.classList.toggle("on", torchOn);
}
async function toggleTorch() {
  const track = torchTrack();
  if (!track) return;
  torchOn = !torchOn;
  try { await track.applyConstraints({ advanced: [{ torch: torchOn }] }); } catch (_) {}
  updateTorchButton();
}

// Focus tuning: after the stream starts, apply continuous + near focus if the
// device exposes those capabilities (constraints in getUserMedia are best-effort,
// so we re-apply here where capabilities are actually known).
function applyFocusTuning() {
  if (!videoStream) return;
  const track = videoStream.getVideoTracks()[0];
  if (!track || !track.getCapabilities) return;
  let caps = {};
  try { caps = track.getCapabilities() || {}; } catch (_) { return; }
  const advanced = [];
  if (caps.focusMode && caps.focusMode.includes("continuous")) {
    advanced.push({ focusMode: "continuous" });
  }
  if (caps.focusDistance) {
    // Aim near the close end of the supported range for label-distance focus.
    const near = caps.focusDistance.min +
      (caps.focusDistance.max - caps.focusDistance.min) * 0.15;
    advanced.push({ focusDistance: near });
  }
  if (advanced.length) {
    track.applyConstraints({ advanced }).catch(() => {});
  }
}

// Tap-to-focus: tapping the preview forces a quick single-shot refocus on the
// label, then returns to continuous — useful when auto-focus is hunting.
async function tapToFocus() {
  if (!videoStream) return;
  const track = videoStream.getVideoTracks()[0];
  if (!track || !track.getCapabilities) return;
  let caps = {};
  try { caps = track.getCapabilities() || {}; } catch (_) { return; }
  if (!caps.focusMode) return;
  try {
    if (caps.focusMode.includes("single-shot")) {
      await track.applyConstraints({ advanced: [{ focusMode: "single-shot" }] });
      // Briefly hold single-shot, then restore continuous for ongoing scanning.
      setTimeout(() => {
        if (caps.focusMode.includes("continuous")) {
          track.applyConstraints({ advanced: [{ focusMode: "continuous" }] }).catch(() => {});
        }
      }, 1200);
    } else if (caps.focusMode.includes("manual") && caps.focusDistance) {
      const near = caps.focusDistance.min +
        (caps.focusDistance.max - caps.focusDistance.min) * 0.12;
      await track.applyConstraints({ advanced: [{ focusMode: "manual", focusDistance: near }] });
    }
    // Quick visual pulse so the user knows the tap registered.
    const frame = $("reader-video");
    if (frame) { frame.classList.add("focus-pulse"); setTimeout(() => frame.classList.remove("focus-pulse"), 350); }
  } catch (_) {}
}

async function stopScanner() {
  if (detectLoop) { cancelAnimationFrame(detectLoop); detectLoop = null; }
  if (zxingReader) { try { zxingReader.reset(); } catch (_) {} zxingReader = null; }
  if (videoStream) {
    // Turn torch off before releasing, so it doesn't stay lit.
    try {
      const t = videoStream.getVideoTracks()[0];
      if (torchOn && t) t.applyConstraints({ advanced: [{ torch: false }] }).catch(() => {});
    } catch (_) {}
    try { videoStream.getTracks().forEach((t) => t.stop()); } catch (_) {}
    videoStream = null;
  }
  torchOn = false;
  pendingCode = null;
  const video = $("reader-video");
  if (video) { try { video.srcObject = null; } catch (_) {} }
}

// Double-read confirm: a code must be seen twice in a row before we accept it.
// This kills one-frame misreads (e.g. a wrong number from a blurry frame).
function onScanCandidate(text) {
  if (!text) return;
  if (scanCooldown) return;
  if (text === pendingCode) {
    pendingCode = null;
    onScan(text);
  } else {
    pendingCode = text;
  }
}

function onScan(decodedText) {
  if (scanCooldown) return;
  if (!decodedText) return;
  scanCooldown = true;
  pendingCode = null;
  scanStatus(`<span class="led"></span> Scanned ${escapeHtml(decodedText)}`);
  addByCode(decodedText);
  setTimeout(() => (scanCooldown = false), 1500);
}

// ---- QR live scanner (QR codes only) ---------------------------------------
// Reuses the same proven approach as the barcode scanner (native BarcodeDetector,
// ZXing fallback) but locked to qr_code, into its own #qr-video element.
let qrStream = null;
let qrDetectLoop = null;
let qrZxingReader = null;
let qrCooldown = false;
let qrPending = null;

// The scanner can serve two places: the machine popup (default — feeds
// addByCode) and the Find Part screen (feeds the stock lookup). qrTarget
// says which video/status elements to use and what to do with a scanned code.
const QR_DEFAULT_TARGET = { videoId: "qr-video", statusId: "qr-status", onCode: (text) => addByCode(text) };
let qrTarget = QR_DEFAULT_TARGET;

function qrStatus(html) { const el = $(qrTarget.statusId); if (el) el.innerHTML = html; }

async function startQrScanner(target) {
  await stopQrScanner();
  qrTarget = target || QR_DEFAULT_TARGET;
  const video = $(qrTarget.videoId);
  if (!video) return;

  try {
    qrStream = await navigator.mediaDevices.getUserMedia({
      video: { facingMode: { ideal: "environment" }, width: { ideal: 1280 }, height: { ideal: 1280 } },
      audio: false,
    });
    video.srcObject = qrStream;
    video.setAttribute("playsinline", "true");
    await video.play();
    qrStatus('<span class="led"></span> Point at a QR code');
  } catch (e) {
    qrStatus('<span class="led" style="background:var(--amber);box-shadow:0 0 0 3px var(--amber-tint)"></span> Camera blocked — switch to Type code');
    return;
  }

  // Path 1: native / polyfilled BarcodeDetector, QR only
  if ("BarcodeDetector" in window) {
    try {
      const detector = new window.BarcodeDetector({ formats: ["qr_code"] });
      const tick = async () => {
        if (!qrStream) return;
        try {
          const codes = await detector.detect(video);
          if (codes && codes.length) onQrCandidate(codes[0].rawValue);
        } catch (_) {}
        qrDetectLoop = requestAnimationFrame(tick);
      };
      qrDetectLoop = requestAnimationFrame(tick);
      return;
    } catch (_) {}
  }

  // Path 2: ZXing fallback
  if (window.ZXingBrowser) {
    try {
      qrZxingReader = new ZXingBrowser.BrowserQRCodeReader
        ? new ZXingBrowser.BrowserQRCodeReader()
        : new ZXingBrowser.BrowserMultiFormatReader();
      qrZxingReader.decodeFromVideoElement(video, (result) => {
        if (result) onQrCandidate(result.getText());
      });
      return;
    } catch (_) {}
  }

  qrStatus('<span class="led" style="background:var(--amber);box-shadow:0 0 0 3px var(--amber-tint)"></span> Scanner not supported here — use Type code');
}

async function stopQrScanner() {
  if (qrDetectLoop) { cancelAnimationFrame(qrDetectLoop); qrDetectLoop = null; }
  if (qrZxingReader) { try { qrZxingReader.reset(); } catch (_) {} qrZxingReader = null; }
  if (qrStream) {
    try { qrStream.getTracks().forEach((t) => t.stop()); } catch (_) {}
    qrStream = null;
  }
  qrPending = null;
  const video = $(qrTarget.videoId);
  if (video) { try { video.srcObject = null; } catch (_) {} }
}

// Double-read confirm (kills one-frame misreads), same pattern as the barcode path.
function onQrCandidate(text) {
  if (!text || qrCooldown) return;
  if (text === qrPending) { qrPending = null; onQrScan(text); }
  else qrPending = text;
}
function onQrScan(text) {
  if (qrCooldown || !text) return;
  qrCooldown = true;
  qrPending = null;
  qrStatus(`<span class="led"></span> Scanned ${escapeHtml(text)}`);
  qrTarget.onCode(text);
  setTimeout(() => (qrCooldown = false), 1500);
}

// ---- OCR mode (read the printed SKU text on damaged labels) -----------------
// Reuses a camera stream into #ocr-video; on capture, Tesseract reads the frame,
// then we pull out the first BRAND+number token (e.g. "SZEN 140051111").
let ocrStream = null;
let ocrBusy = false;

function ocrStatus(html) { $("ocr-status").innerHTML = html; }

async function startOcrCamera() {
  await stopOcrCamera();
  const video = $("ocr-video");
  if (!video) return;
  try {
    ocrStream = await navigator.mediaDevices.getUserMedia({
      video: { facingMode: "environment" },
      audio: false,
    });
    video.srcObject = ocrStream;
    video.setAttribute("playsinline", "true");
    await video.play();
    ocrStatus('<span class="led"></span> Frame the printed code, then tap Read');
  } catch (e) {
    ocrStatus('<span class="led" style="background:var(--amber);box-shadow:0 0 0 3px var(--amber-tint)"></span> Camera blocked — switch to Type code');
  }
}

async function stopOcrCamera() {
  if (ocrStream) {
    try { ocrStream.getTracks().forEach((t) => t.stop()); } catch (_) {}
    ocrStream = null;
  }
  const video = $("ocr-video");
  if (video) { try { video.srcObject = null; } catch (_) {} }
}

// Pull a SKU-shaped token out of raw OCR text: a brand prefix (letters) followed
// by a long number (e.g. "SZEN 140051111"). OM SKUs have a 5+ digit run, so this
// ignores short rack/bin codes like "BK3410" or "R3D6" that share the label.
// OCR sometimes confuses letters/digits inside the number — we fix the common ones.
function fixDigits(s) {
  return s
    .replace(/O/g, "0").replace(/Q/g, "0").replace(/D/g, "0")
    .replace(/I/g, "1").replace(/L/g, "1")
    .replace(/S/g, "5").replace(/B/g, "8").replace(/Z/g, "2").replace(/G/g, "6");
}
function extractSku(text) {
  if (!text) return null;
  const cleaned = text.toUpperCase().replace(/[^A-Z0-9 \n]/g, " ");
  // Allow the "number" part to contain OCR-confused letters; we repair them after.
  const matches = [...cleaned.matchAll(/([A-Z]{2,6})\s*([0-9OQDILSBZG]{5,12})/g)];
  if (!matches.length) return null;
  // Prefer the candidate with the longest run — that's the real part number.
  matches.sort((a, b) => b[2].length - a[2].length);
  const brand = matches[0][1];
  const number = fixDigits(matches[0][2]);
  return brand + " " + number;
}

async function captureAndRead() {
  if (ocrBusy) return;
  const video = $("ocr-video");
  if (!video || !ocrStream) { ocrStatus('<span class="led" style="background:var(--amber);box-shadow:0 0 0 3px var(--amber-tint)"></span> Camera not ready'); return; }
  if (!window.Tesseract) { ocrStatus('<span class="led" style="background:var(--amber);box-shadow:0 0 0 3px var(--amber-tint)"></span> Text reader still loading — try again'); return; }

  ocrBusy = true;
  ocrStatus('<span class="led"></span> Reading…');

  const vw = video.videoWidth || 1280;
  const vh = video.videoHeight || 720;

  // Crop to a central horizontal band — the user aims the SKU line into the guide.
  // This drops the surrounding label noise (barcode, rack codes) so OCR focuses
  // only on the printed part number. Band = full width, middle ~28% of height.
  const bandH = Math.round(vh * 0.28);
  const bandY = Math.round((vh - bandH) / 2);

  // Upscale 2x — Tesseract is far more accurate on larger characters.
  const scale = 2;
  const canvas = document.createElement("canvas");
  canvas.width = vw * scale;
  canvas.height = bandH * scale;
  const ctx = canvas.getContext("2d");
  ctx.drawImage(video, 0, bandY, vw, bandH, 0, 0, canvas.width, canvas.height);

  // Grayscale + contrast boost so crisp black text pops from the label background.
  try {
    const img = ctx.getImageData(0, 0, canvas.width, canvas.height);
    const d = img.data;
    for (let i = 0; i < d.length; i += 4) {
      const g = 0.299 * d[i] + 0.587 * d[i + 1] + 0.114 * d[i + 2];
      // Soft threshold: push toward black/white without going fully binary.
      const v = g < 110 ? Math.max(0, g - 40) : Math.min(255, g + 40);
      d[i] = d[i + 1] = d[i + 2] = v;
    }
    ctx.putImageData(img, 0, 0);
  } catch (_) { /* if getImageData is blocked, proceed with the colour crop */ }

  try {
    const { data } = await Tesseract.recognize(canvas, "eng", {
      tessedit_char_whitelist: "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789 ",
      // PSM 6 = treat the image as a single uniform block of text (one line band).
      tessedit_pageseg_mode: "6",
    });
    const raw = (data && data.text ? data.text : "").trim();
    const sku = extractSku(raw);
    if (sku) {
      ocrStatus(`<span class="led"></span> Read ${escapeHtml(sku)}`);
      addByCode(sku);
    } else {
      ocrStatus('<span class="led" style="background:var(--amber);box-shadow:0 0 0 3px var(--amber-tint)"></span> No code found — line the text up in the guide and try again');
    }
  } catch (e) {
    ocrStatus('<span class="led" style="background:var(--amber);box-shadow:0 0 0 3px var(--amber-tint)"></span> Could not read — try again');
  } finally {
    ocrBusy = false;
  }
}

// ---- Mode toggle (part-entry methods within Open Service) -------------------
function setMode(mode) {
  currentMode = mode;
  document.querySelectorAll("#mode-toggle button").forEach((b) =>
    b.classList.toggle("on", b.dataset.mode === mode)
  );

  const qrPane = $("qr-pane");
  if (qrPane) qrPane.style.display = mode === "qr" ? "flex" : "none";
  const manualPane = $("manual-pane");
  if (manualPane) manualPane.style.display = mode === "manual" ? "block" : "none";

  if (mode === "qr") startQrScanner();
  else stopQrScanner();
  if (mode === "manual") {
    const ci = $("code-input"); if (ci) { ci.value = ""; ci.focus(); }
    const cr = $("code-results"); if (cr) cr.innerHTML = "";
  }
}

// ---- Event wiring ----------------------------------------------------------
// Role selection
// Technician is the only role with a Chinese interface (i18n.js), and that
// layer is installed at page load. So when someone crosses into or out of
// Technician we reload; every other role change stays instant as before.
function languageChanges(nextRole) {
  return (getRole() === "tech") !== (nextRole === "tech");
}
$("switch-role").addEventListener("click", () => {
  const reload = languageChanges("");
  setUser("");
  if (reload) { location.reload(); return; } // reopens on the picker
  renderStaffPicker();
  showScreen("role");
});

// Home navigation
document.querySelectorAll(".home-btn").forEach((b) =>
  b.addEventListener("click", () => {
    const go = b.dataset.go;
    if (go === "new") { resetNewServiceForm(); showScreen("new"); }
    else if (go === "open") { enterOpenService(); }
    else if (go === "close") { enterCloseService(); }
    else if (go === "view") { enterViewSlips(); }
    else if (go === "find") { enterFindPart(); }
    else if (go === "quote") { enterNeedToQuote(); }
    else if (go === "requests") { enterPurchaser(); }
    else if (go === "ipl") { enterIpl(); }
  })
);
$("home-link").addEventListener("click", goHome);

// ---- Find Part --------------------------------------------------------------
// Search AutoCount by description or code; tap a result to see the stock card
// (part no., description, shelf location, balance qty). Read-only.
function enterFindPart() {
  $("fp-q").value = "";
  $("fp-results").innerHTML = "";
  $("fp-detail").style.display = "none";
  $("fp-detail").innerHTML = "";
  $("fp-order-more").style.display = "none";
  fpCurrentPart = null;
  $("fp-scan-area").style.display = "none";
  $("fp-scan").style.display = "flex";
  showScreen("find");
  setTimeout(() => $("fp-q").focus(), 50);
}
// QR scanning inside Find Part: scan a part's code to jump straight to its
// stock card. Uses the shared scanner pointed at Find Part's own elements.
function stopFindScan() {
  $("fp-scan-area").style.display = "none";
  $("fp-scan").style.display = "flex";
  try { stopQrScanner(); } catch (_) {}
}
$("fp-scan").addEventListener("click", () => {
  $("fp-results").innerHTML = "";
  $("fp-detail").style.display = "none";
  $("fp-order-more").style.display = "none";
  $("fp-scan").style.display = "none";
  $("fp-scan-area").style.display = "flex";
  startQrScanner({
    videoId: "fp-video",
    statusId: "fp-scan-status",
    onCode: (code) => {
      stopFindScan();
      showPartStock(code);
    },
  });
});
$("fp-scan-stop").addEventListener("click", stopFindScan);

let fpDebounce = null;
$("fp-q").addEventListener("input", () => {
  clearTimeout(fpDebounce);
  const q = $("fp-q").value.trim();
  const box = $("fp-results");
  $("fp-detail").style.display = "none";
  $("fp-order-more").style.display = "none";
  if (q.length < 2) { box.innerHTML = ""; return; }
  fpDebounce = setTimeout(async () => {
    try {
      const data = await api(`/api/parts-search?q=${encodeURIComponent(q)}`);
      const list = data.results || [];
      if (!list.length) {
        box.innerHTML = `<div class="fp-empty">No matching parts</div>`;
        return;
      }
      box.innerHTML = list.map((p) =>
        `<button type="button" class="company-option" data-code="${escapeAttr(p.item_code)}">
           <span class="fp-opt-desc">${escapeHtml(p.description)}${p.desc2 ? ` <span class="fp-opt-model">· ${escapeHtml(p.desc2)}</span>` : ""}</span>
           <span class="fp-opt-code mono">${escapeHtml(p.item_code)}</span>
         </button>`
      ).join("");
      box.querySelectorAll(".company-option").forEach((btn) =>
        btn.addEventListener("click", () => showPartStock(btn.dataset.code))
      );
    } catch (_) { box.innerHTML = ""; }
  }, 250);
});

let fpCurrentPart = null; // the part shown in the Find Part detail card

async function showPartStock(code) {
  const detail = $("fp-detail");
  $("fp-results").innerHTML = "";
  detail.style.display = "block";
  $("fp-order-more").style.display = "none";
  fpCurrentPart = null;
  detail.innerHTML = `<div class="fp-loading">Looking up stock…</div>`;
  try {
    const p = await api(`/api/part-stock/${encodeURIComponent(code)}`);
    fpCurrentPart = p;
    const qty = Number(p.bal_qty);
    const qtyStr = Number.isInteger(qty) ? String(qty) : qty.toFixed(2);
    detail.innerHTML = `
      <div class="fp-row"><span class="fp-lbl">Part No.</span><span class="fp-val mono">${escapeHtml(p.item_code)}</span></div>
      <div class="fp-row"><span class="fp-lbl">Description</span><span class="fp-val">${escapeHtml(p.description)}${p.desc2 ? `<br><span class="fp-val-model">${escapeHtml(p.desc2)}</span>` : ""}</span></div>
      <div class="fp-row"><span class="fp-lbl">Location / Shelf</span><span class="fp-val">${p.shelf ? escapeHtml(p.shelf) : "—"}</span></div>
      <div class="fp-row"><span class="fp-lbl">Bal. Qty</span><span class="fp-val fp-qty ${qty > 0 ? "fp-qty-ok" : "fp-qty-zero"}">${qtyStr}${p.uom ? " " + escapeHtml(p.uom) : ""}</span></div>`;
    $("fp-order-more").style.display = "block";
  } catch (e) {
    detail.innerHTML = `<div class="fp-empty">${escapeHtml(e.message || "Lookup failed")}</div>`;
  }
}

// ---- Order More popup -------------------------------------------------------
// Opened from two places now — the Find Part card and the IPL part sheet — so
// the part being ordered is held here rather than read back off either screen.
let orderPart = null;

// Ordering runs in two steps: type the quantity, then confirm what is about to
// be sent. A reorder request goes to the purchaser and gets acted on, so a
// mistyped quantity is worth one deliberate tap to catch.
function showOrderStep(step) {
  const confirming = step === "confirm";
  $("om-qty-field").style.display = confirming ? "none" : "";
  $("om-confirm").style.display = confirming ? "" : "none";
  $("om-back").style.display = confirming ? "" : "none";
  $("om-submit").textContent = confirming ? "Confirm order" : "Submit request";
}

function openOrderModal(part) {
  if (!part || !part.item_code) return;
  orderPart = part;
  $("om-part-name").textContent = `${part.description} · ${part.item_code}`;
  $("om-qty").value = "";
  showOrderStep("qty");
  $("order-modal").style.display = "flex";
  document.body.style.overflow = "hidden";
  setTimeout(() => $("om-qty").focus(), 50);
}

$("fp-order-more").addEventListener("click", () => openOrderModal(fpCurrentPart));

function closeOrderModal() {
  $("order-modal").style.display = "none";
  // Ordering from the IPL stacks this on top of the part sheet, which is still
  // open underneath — releasing the scroll lock here would let the page behind
  // it slide about.
  if ($("ipl-modal").style.display !== "flex") document.body.style.overflow = "";
}
$("om-close").addEventListener("click", closeOrderModal);
$("om-back").addEventListener("click", () => {
  showOrderStep("qty");
  $("om-qty").focus();
});

$("om-submit").addEventListener("click", async () => {
  if (!orderPart) return;
  const qty = parseInt($("om-qty").value, 10);
  const requester = userName();
  if (!Number.isFinite(qty) || qty < 1) { toast("Enter an order quantity", "err"); return; }
  // Nobody signed in means nothing to put in the requester column, and the
  // purchaser would have no idea who asked.
  if (!requester) { toast("Choose your name from the top bar first", "err"); return; }

  // First tap shows what is about to be sent; the second sends it.
  if ($("om-confirm").style.display === "none") {
    $("om-check-line").textContent = `Order ${qty} × ${orderPart.description}`;
    $("om-check-who").textContent = `${orderPart.item_code} · requested by ${requester}`;
    showOrderStep("confirm");
    return;
  }

  $("om-submit").disabled = true;
  try {
    await api(`/api/part-requests`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        item_code: orderPart.item_code,
        description: orderPart.description,
        qty_requested: qty,
        requester,
      }),
    });
    toast("Request submitted", "ok");
    closeOrderModal();
  } catch (e) {
    toast(e.message, "err");
  }
  $("om-submit").disabled = false;
});

// ---- Need to Quote: what the technicians have handed back -------------------
// A technician finishing a repair marks the slip "Need to Quote". Until now
// that status was only visible to whoever happened to open the slip; this is
// the list of them, so nothing sits waiting because nobody knew.
async function enterNeedToQuote() {
  showScreen("quote");
  renderPushRow();
  const wrap = $("q-list");
  wrap.innerHTML = `<div class="fp-loading">Loading…</div>`;
  try {
    const rows = await api(`/api/slips?status=need_quote`);
    if (!rows.length) {
      wrap.innerHTML = `<div class="fp-empty">Nothing waiting to be quoted</div>`;
      refreshQuoteCount();
      return;
    }
    wrap.innerHTML = rows.map((s) => {
      const all = s.machines || [];
      // Machines are quoted one at a time now, so the count on its own would be
      // misleading: two machines, one waiting, reads as two to price.
      const waiting = all.filter((m) => m.quote_status === "NEED_QUOTE");
      const list = (waiting.length ? waiting : all).map((m) => m.machine_desc);
      const machines = all.length;
      const created = formatDate(s.created_at);
      return `
      <button type="button" class="slip-card" data-slip="${escapeAttr(s.slip_number)}">
        <div class="slip-card-top">
          <strong>${escapeHtml(s.slip_number)}</strong>
          <span class="vs-status vs-NEED_QUOTE">Need to Quote</span>
        </div>
        <div class="slip-card-co">${escapeHtml(s.company)}</div>
        <div class="slip-card-sub">${escapeHtml(list.join(", "))}${
          waiting.length && waiting.length < machines ? ` · ${waiting.length} of ${machines}` : ""
        }${created ? " · " + escapeHtml(created) : ""}</div>
      </button>`;
    }).join("");
    // Straight into View Slips, which already lists every part with its price
    // and carries the "Mark as Quoted" button — no second copy of any of it.
    wrap.querySelectorAll(".slip-card").forEach((b) =>
      b.addEventListener("click", () => {
        showScreen("view");
        if (viewSearch) viewSearch.reset();
        onViewSlipChosen(b.dataset.slip);
      })
    );
  } catch (e) {
    wrap.innerHTML = `<div class="fp-empty">${escapeHtml(e.message || "Could not load")}</div>`;
  }
  refreshQuoteCount();
}

// The count on the home tile. Cheap enough to refresh whenever home is shown,
// and it is the whole point of the feature: seeing there is something waiting
// without having to go looking for it.
async function refreshQuoteCount() {
  const badge = $("quote-count");
  if (!badge) return;
  const tile = document.querySelector('#screen-home .home-btn[data-go="quote"]');
  if (!tile || tile.style.display === "none") return;
  try {
    const rows = await api(`/api/slips?status=need_quote`);
    const n = rows.length;
    badge.textContent = String(n);
    badge.style.display = n ? "grid" : "none";
  } catch (_) {
    badge.style.display = "none";
  }
}

// ---- Push notifications ----------------------------------------------------
// Per device. A subscription belongs to one browser on one phone, so someone
// with a phone and a tablet turns it on twice and is told on both.
//
// What has to be true for the button to do anything: HTTPS with a certificate
// the device trusts, and on iOS the app added to the Home Screen, on 16.4 or
// later. Safari tabs on iOS get nothing at all, so the row is hidden there
// rather than offering something that cannot work.
function pushSupported() {
  return "serviceWorker" in navigator &&
         "PushManager" in window &&
         "Notification" in window;
}

function urlBase64ToUint8Array(base64) {
  const padded = (base64 + "=".repeat((4 - (base64.length % 4)) % 4))
    .replace(/-/g, "+").replace(/_/g, "/");
  const raw = atob(padded);
  return Uint8Array.from([...raw].map((c) => c.charCodeAt(0)));
}

// navigator.serviceWorker.ready never rejects and never times out: with no
// worker registered it simply hangs for ever. Waiting on it before checking
// anything else left the row stuck on its default text and the button dead to
// the touch. Race it, so a worker that is not there yet reports as much.
function swReady(ms = 4000) {
  if (!("serviceWorker" in navigator)) return Promise.resolve(null);
  return Promise.race([
    navigator.serviceWorker.ready,
    new Promise((resolve) => setTimeout(() => resolve(null), ms)),
  ]);
}

async function currentPushSubscription() {
  if (!pushSupported()) return null;
  const reg = await swReady();
  return reg ? reg.pushManager.getSubscription() : null;
}

async function renderPushRow() {
  const row = $("push-row");
  if (!row) return;
  if (!pushSupported()) { row.style.display = "none"; return; }
  row.style.display = "flex";

  const btn = $("push-toggle");
  const sub = $("push-sub");

  // Checked first, and without awaiting: it is the one answer that settles the
  // row on its own, and it costs nothing to read.
  if (Notification.permission === "denied") {
    btn.style.display = "none";
    sub.textContent = "Notifications are blocked for this site in the phone's settings";
    return;
  }
  const existing = await currentPushSubscription();
  btn.style.display = "";
  btn.disabled = false;

  // Shown whether this device is on or off. "0 devices" is the answer to most
  // of the ways this looks broken - everyone assumes someone else turned it on.
  let devices = null;
  try { devices = (await api("/api/push/status")).devices; } catch (_) {}
  const across = devices === null ? ""
    : devices === 0 ? " · no devices are being notified yet"
    : ` · ${devices} device${devices === 1 ? "" : "s"} being notified`;

  const test = $("push-test");
  if (existing) {
    btn.textContent = "Turn off";
    sub.textContent = "On for this device" + across;
    if (test) test.style.display = "";
  } else {
    btn.textContent = "Turn on";
    sub.textContent = "Notify this device when a technician finishes a repair" + across;
    if (test) test.style.display = "none";
  }
}

// Proves the whole chain from this device: app to server, server to Google or
// Apple, and back to the phone. Without it "no notification arrived" has half a
// dozen possible causes and no way to tell them apart.
async function sendTestPush() {
  const test = $("push-test");
  test.disabled = true;
  const was = test.textContent;
  test.textContent = "Sending…";
  try {
    const sub = await currentPushSubscription();
    if (!sub) { toast("This device is not subscribed", "err"); return; }
    const r = await api("/api/push/test", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ endpoint: sub.endpoint }),
    });
    if (r.ok) toast("Sent — it should appear in a moment", "ok");
    else toast(r.reason || "The test did not go through", "err");
  } catch (e) {
    toast(e.message || "The test did not go through", "err");
  }
  test.textContent = was;
  test.disabled = false;
  renderPushRow();
}

async function togglePush() {
  const btn = $("push-toggle");
  btn.disabled = true;
  try {
    const reg = await swReady();
    if (!reg) {
      toast("The app is still starting up — try again in a moment", "err");
      btn.disabled = false;
      return;
    }
    const existing = await reg.pushManager.getSubscription();

    if (existing) {
      await api("/api/push/unsubscribe", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ endpoint: existing.endpoint }),
      }).catch(() => {});
      await existing.unsubscribe();
      toast("Notifications off for this device", "ok");
    } else {
      // Must be asked from a tap. iOS refuses outright otherwise, and Chrome
      // holds it against the site.
      const permission = await Notification.requestPermission();
      if (permission !== "granted") {
        toast(permission === "denied"
          ? "Notifications blocked — allow them in the phone's settings"
          : "Notifications not enabled", "err");
        await renderPushRow();
        return;
      }
      const { key } = await api("/api/push/key");
      const subscription = await reg.pushManager.subscribe({
        // Required, and the only value browsers accept: every push must show
        // something. There is no silent background push here.
        userVisibleOnly: true,
        applicationServerKey: urlBase64ToUint8Array(key),
      });
      await api("/api/push/subscribe", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          subscription: subscription.toJSON(),
          user_id: (getUser() || {}).id || "",
          role: getRole(),
        }),
      });
      toast("Notifications on for this device", "ok");
    }
  } catch (e) {
    toast(e.message || "Could not change notifications", "err");
  }
  await renderPushRow();
}

// Tapping a notification asks an already-open window to move, rather than
// opening a second one.
if ("serviceWorker" in navigator) {
  navigator.serviceWorker.addEventListener("message", (e) => {
    if (e.data && e.data.type === "go" && e.data.screen === "quote") enterNeedToQuote();
  });
}

// ...and a notification that opened the app cold arrives as ?go=quote.
(function openFromNotification() {
  try {
    const go = new URLSearchParams(location.search).get("go");
    if (go === "quote") {
      // After the role has been read, or the screen is shown to nobody.
      setTimeout(() => { if (getUser()) enterNeedToQuote(); }, 300);
    }
  } catch (_) {}
})();

